// What a running reviewer is to leave as it found it, and what the gate tells
// it and the status tool when something moved. The reads take a `Git` the hook
// supplies, as git.ts does; the rest is pure.

import { firstLine, sha, worktreeTree, type Git } from './git';

// HEAD's commit and branch, the staged entries, the working tree and the local
// and worktree config. null marks a part git could not read.
export type RepoState = {
  head: string | null;
  index: string | null;
  work: string | null;
  config: string | null;
};

export const UNREAD: RepoState = { head: null, index: null, work: null, config: null };

// A state and, when a read threw, why.
export type Capture = { state: RepoState; why: string | null };

const PARTS: Record<keyof RepoState, string> = {
  head: 'HEAD',
  index: 'the staged content',
  work: 'the working tree',
  config: 'the local git config',
};

// Neither read takes the index lock that `write-tree` would. The listing is
// hashed inside git, so a large index is not cut at the output limit.
const INDEX_DIGEST =
  'list=$(git ls-files -s) || exit 2; printf %s "$list" | git hash-object --stdin';

// A working tree git could not build is unreadable alone, so the other parts
// are still compared, and its reason is kept.
export async function repoStateOf(git: Git, root: string): Promise<Capture> {
  const opts = { cwd: root };
  // rev-parse exits 1 on an unborn branch, symbolic-ref on a detached HEAD;
  // both exiting 1 is a read that failed, since a killed child reads as 1.
  const commit = await git(['git', 'rev-parse', '--verify', '-q', 'HEAD'], opts);
  const branch = await git(['git', 'symbolic-ref', '-q', 'HEAD'], opts);
  const index = await git(['sh', '-c', INDEX_DIGEST], opts);
  const config = await git(['git', 'config', '--list', '--show-scope', '-z'], opts);
  const headRead =
    (commit.exitCode === 0 && branch.exitCode <= 1) ||
    (commit.exitCode === 1 && branch.exitCode === 0);
  let why: string | null = null;
  const work = await worktreeTree(git, root).catch((error: unknown) => {
    why = error instanceof Error ? error.message : String(error);
    return null;
  });
  const state: RepoState = {
    head: headRead ? `${commit.stdout.trim()} ${branch.stdout.trim()}` : null,
    index: index.exitCode === 0 ? sha(index.stdout) : null,
    work,
    config: config.exitCode === 0 ? ownConfig(config.stdout) : null,
  };
  return { state, why };
}

// `-z` prints scope, then `key\nvalue`, each ended by NUL, so a value that
// spans lines stays whole.
export function ownConfig(z: string): string {
  const fields = z.split('\0');
  const own: string[] = [];
  for (let i = 0; i + 1 < fields.length; i += 2) {
    if (fields[i] === 'local' || fields[i] === 'worktree')
      own.push(`${fields[i]}\0${fields[i + 1]}`);
  }
  return own.join('\0');
}

export function repoChanges(
  a: RepoState,
  b: RepoState,
): { changed: string[]; unreadable: string[] } {
  const changed: string[] = [];
  const unreadable: string[] = [];
  for (const [k, name] of Object.entries(PARTS) as [keyof RepoState, string][]) {
    if (a[k] === null || b[k] === null) unreadable.push(name);
    else if (a[k] !== b[k]) changed.push(name);
  }
  return { changed, unreadable };
}

export function insideRepo(path: string, top: string): boolean {
  return path === top || path.startsWith(`${top}/`);
}

// The notes for the reviewer and the records for the status tool.
export function containmentReport(r: {
  type: string;
  command: string;
  before: Capture;
  after: Capture;
  background: boolean;
}): { notes: string[]; records: string[] } {
  const shown = firstLine(r.command).slice(0, 80);
  const { changed, unreadable } = repoChanges(r.before.state, r.after.state);
  const notes: string[] = [];
  const records: string[] = [];
  if (changed.length > 0) {
    const what = changed.join(', ');
    records.push(`${r.type}: ${what} changed while \`${shown}\` ran`);
    notes.push(
      `review-cycle: ${what} of the repository under review changed while this command ran, by it or by another agent. If this command made the change, put it back; either way, say so in your report, and keep scratch work in a private directory from mktemp -d.`,
    );
  }
  if (unreadable.length > 0) {
    const whys = [...new Set([r.before.why, r.after.why])].filter((w) => w !== null);
    const what = `${unreadable.join(', ')}${whys.length === 0 ? '' : ` (${whys.join('; ')})`}`;
    records.push(`${r.type}: could not check ${what} while \`${shown}\` ran`);
    notes.push(
      `review-cycle could not check whether this command changed ${what} of the repository under review.`,
    );
  }
  if (r.background) {
    notes.push(
      'review-cycle: this command runs in the background, so what it changes in the repository under review after it returns is not checked.',
    );
  }
  return { notes, records };
}

files.hooks/edits.ts:
// Notes the files a Bash command changed, so its edits go through Edit and
// Write, where the comment-slop and settings checks run. No `$`: the snapshot
// and the comparison are passed in, as git.ts takes its runner.
//
// The working tree is compared around the command; `mayWrite` only picks the
// commands worth measuring, so a false yes costs time, not accuracy.

import { basename, BUILTIN_RUNNERS, every, INTERPRETERS, KEYWORDS } from './command';
import { messageOf } from './git';
import { assignmentName, parse, type ShellAliases, type Statement, type Word } from './shell';

// Writers and runners the gate does not treat as running code.
const WRITERS = new Set([
  'tee',
  'sed',
  'gsed',
  'awk',
  'gawk',
  'cp',
  'mv',
  'install',
  'truncate',
  'dd',
  'rsync',
  'sponge',
  'patch',
  'xargs',
]);
const PYTHON = /^python[0-9.]*$/;
// Wrappers that run the command after them, besides the reserved words.
const WRAPPERS = new Set(['time', 'env', 'exec', 'command', 'nohup', 'nice']);
// The paths a note lists before it counts the rest.
const SHOWN = 10;

// A redirect whose target the shell computes may land anywhere.
const writesFile = (w: Word): boolean => w.dynamic || !w.text.startsWith('/dev/');

const nameOf = (w: Word): string => basename(w.text).replace(/\.exe$/i, '');

// Runners whose names are also ordinary words and paths (`git add .`,
// `rg expect`, `pnpm run watch`): they count only as the command itself,
// which runsScript checks.
const COMMAND_ONLY = new Set([
  ...BUILTIN_RUNNERS,
  'expect',
  'watch',
  'script',
  'sudo',
  'doas',
  'uv',
  'mise',
  'nix-shell',
]);

function names(w: Word): boolean {
  const name = nameOf(w);
  if (COMMAND_ONLY.has(name)) return false;
  return INTERPRETERS.has(name) || WRITERS.has(name) || PYTHON.test(name);
}

const beforeCommand = (w: Word): boolean =>
  assignmentName(w) !== null ||
  KEYWORDS.has(w.text) ||
  WRAPPERS.has(w.text) ||
  w.text.startsWith('-');

// A script run by its path, or a command-only runner, behind any
// assignments, flags, reserved words and wrappers.
function runsScript(st: Statement): boolean {
  const command = st.words.find((w) => !beforeCommand(w));
  if (command === undefined) return false;
  return command.text.includes('/') || COMMAND_ONLY.has(nameOf(command));
}

// Any word counts, not only the first, so a writer behind `if`, `time`,
// `env`, `sudo`, `xargs` or a wrapper still counts. A command it cannot read
// counts.
export function mayWrite(command: string, aliases: ShellAliases = new Map()): boolean {
  const parsed = parse(command, aliases);
  if ('error' in parsed) return true;
  if (parsed.bareWrites.some(writesFile)) return true;
  const writes = (st: Statement): boolean =>
    st.writes.some(writesFile) || st.words.some(names) || runsScript(st);
  return every(parsed.statements, (st) => (writes(st) ? 'writes' : null)) !== null;
}

// The comparison sees every change made while the command ran, a parallel
// Edit or the user's own save included, so the note cannot claim the command
// made them.
export function editNote(paths: readonly string[]): string {
  const shown = paths.slice(0, SHOWN).join(', ');
  const more = paths.length > SHOWN ? ` and ${paths.length - SHOWN} more` : '';
  return `review-cycle: files changed while this command ran: ${shown}${more}. If the command made those edits, make file changes with Edit or Write instead: the comment-slop and settings checks run there, not on Bash.`;
}

export function editsSkipped(why: string): string {
  return `review-cycle: could not check which files this command changed (${why}).`;
}

// Runs the command between two snapshots and names what changed. Never
// rejects for a failed measurement: the command runs, and a failure becomes
// the note. `diff` returns null when it cannot compare.
export async function measureEdits<R>(
  snapshot: () => Promise<string>,
  diff: (before: string, after: string) => Promise<string[] | null>,
  run: () => Promise<R>,
): Promise<{ result: R; note: string | null }> {
  let before: string;
  try {
    before = await snapshot();
  } catch (error) {
    return { result: await run(), note: editsSkipped(messageOf(error)) };
  }
  const result = await run();
  try {
    const after = await snapshot();
    if (after === before) return { result, note: null };
    const changed = await diff(before, after);
    if (changed === null) return { result, note: editsSkipped('git could not compare the trees') };
    return { result, note: changed.length === 0 ? null : editNote(changed) };
  } catch (error) {
    return { result, note: editsSkipped(messageOf(error)) };
  }
}

