// What a GitHub write is on the stop-before ladder, read from a `gh api` call
// or a GitHub MCP tool call. Pure: no `$`, no I/O.

import type { Word } from './shell';

// Where a gh write runs: `elsewhere` when something outside its words picks
// the repository, `beside` when another step in the command may.
export type GhContext = 'fixed' | 'elsewhere' | 'beside';

// `asks` says why the push asks whatever the setting; a `force` one needs a
// request for a bare force, since the API has no lease.
export type Asking = { asks: string; force: boolean };
export const asking = (asks: string, force: boolean): Asking => ({ asks, force });

// `head` is a pull request's own branch, looked up by `gh pr view <head>`.
export type PushRef =
  | { branch: string; repo: string | null; force?: never }
  | { head: readonly string[]; force?: never }
  | Asking;

export type Unlookable = { cannot: Exclude<GhContext, 'fixed'> | 'unnamed' };

export type GhAction =
  | { kind: 'pr' }
  // `auto` waits for what GitHub requires to merge: `gh pr merge --auto`.
  | { kind: 'merge'; admin: boolean; auto: boolean; lookup: readonly string[] | Unlookable }
  | { kind: 'approve' }
  | { kind: 'comment' }
  | { kind: 'release' }
  | { kind: 'push'; ref: PushRef }
  | { kind: 'unread'; why: string; remedy?: string };

// `gh api`'s options that take a value (gh 2.102.0's `gh api --help`), and
// the short ones among them, which take the rest of a cluster (`-XPOST`).
const API_VALUE = new Set([
  '-F',
  '--field',
  '-f',
  '--raw-field',
  '-H',
  '--header',
  '-q',
  '--jq',
  '-X',
  '--method',
  '-p',
  '--preview',
  '-t',
  '--template',
  '--cache',
  '--hostname',
  '--input',
]);
const API_SHORT_VALUE = 'FfHqXpt';
const FIELD = new Set(['-F', '--field', '-f', '--raw-field']);

// A field's value, or null when it is built at run time or read from a file
// (`-F body=@notes.md`).
type Fields = Map<string, string | null>;

type ApiCall = {
  // The method `-X` names, upper-cased; `?` when it is built at run time.
  method: string | null;
  endpoint: Word | null;
  // A word built at run time that may be options (`"$ARGS"`, `$X`), not a
  // value or an endpoint with a written-out start.
  opaque: boolean;
  fields: Fields;
  // A field whose name is built at run time, so any field may hide in it.
  unnamed: boolean;
  input: boolean;
  hostname: boolean;
};

// The option a word is and its value, when it takes one: `-X POST`, `-XPOST`,
// `-X=POST`, `--method=POST`, `-iXPOST`.
function optionAt(words: Word[], i: number): { name: string; value: Word | null; next: number } {
  const w = words[i]!;
  const t = w.text;
  const long = /^(--[^=]+)=([\s\S]*)$/.exec(t);
  if (long?.[1] !== undefined) {
    return { name: long[1], value: { ...w, text: long[2] ?? '' }, next: i + 1 };
  }
  if (t.startsWith('--')) {
    return API_VALUE.has(t)
      ? { name: t, value: words[i + 1] ?? null, next: i + 2 }
      : { name: t, value: null, next: i + 1 };
  }
  for (let at = 1; at < t.length; at++) {
    const letter = t.charAt(at);
    if (!API_SHORT_VALUE.includes(letter)) continue;
    const rest = t.slice(at + 1).replace(/^=/, '');
    return rest === ''
      ? { name: `-${letter}`, value: words[i + 1] ?? null, next: i + 2 }
      : { name: `-${letter}`, value: { ...w, text: rest }, next: i + 1 };
  }
  return { name: t, value: null, next: i + 1 };
}

// The words after `gh api`.
function readApi(words: Word[]): ApiCall {
  const call: ApiCall = {
    method: null,
    endpoint: null,
    opaque: false,
    fields: new Map(),
    unnamed: false,
    input: false,
    hostname: false,
  };
  let i = 0;
  while (i < words.length) {
    const w = words[i]!;
    // A written-out start (`repos/…/$PR`) makes the word the endpoint.
    if (w.dynamic && /^[$`]/.test(w.text)) {
      call.opaque = true;
      i++;
      continue;
    }
    if (!w.text.startsWith('-') || w.text === '-') {
      call.endpoint ??= w;
      i++;
      continue;
    }
    const { name, value, next } = optionAt(words, i);
    i = next;
    if (name === '-X' || name === '--method') {
      call.method = value === null || value.dynamic ? '?' : value.text.toUpperCase();
    } else if (FIELD.has(name) && value !== null) {
      const eq = value.text.indexOf('=');
      const key = eq === -1 ? value.text : value.text.slice(0, eq);
      if (/[$`]/.test(key)) call.unnamed = true;
      const raw = eq === -1 ? '' : value.text.slice(eq + 1);
      // A typed field reads a file (`@f`) or fills in `{branch}` and the like.
      const typed = (name === '-F' || name === '--field') && /^@|\{\w+\}/.test(raw);
      call.fields.set(key, value.dynamic || typed ? null : raw);
    } else if (name === '--input') call.input = true;
    else if (name === '--hostname') call.hostname = true;
  }
  return call;
}

// A branch as GitHub's ref APIs take it, or why the push it names asks: `null`
// is a name read at run time, `undefined` none at all.
function branchOf(name: string | null | undefined, missing: string): string | Asking {
  if (name === null) {
    return asking('the branch it names is built at run time or read from a file', false);
  }
  if (name?.startsWith('refs/tags/')) return asking('it pushes a tag', false);
  if (name?.startsWith('refs/') && !name.startsWith('refs/heads/')) {
    return asking(`it writes \`${name}\`, which is no branch`, false);
  }
  const branch = name?.replace(/^refs\/heads\//, '');
  return branch === undefined || branch === '' ? asking(missing, false) : branch;
}

function pushRef(
  name: string | null | undefined,
  missing: string,
  repo: string | null,
  where: GhContext,
): PushRef {
  if (where === 'elsewhere') return asking('where it pushes is picked outside its words', false);
  const branch = branchOf(name, missing);
  if (typeof branch !== 'string') return branch;
  if (where === 'beside' && repo === null) {
    return asking('another step in the command can change which repository it reaches', false);
  }
  return { branch, repo };
}

// What a REST write to `repos/<owner>/<repo>/<path>` is on the ladder.
function restAction(
  method: string,
  path: string,
  repo: string | null,
  call: ApiCall,
  where: GhContext,
): GhAction | null {
  const field = (key: string) => (call.unnamed || call.input ? null : call.fields.get(key));
  const unknown = (key: string) => call.input || call.unnamed || call.fields.get(key) === null;
  const push = (name: string | null | undefined, missing: string): GhAction => ({
    kind: 'push',
    ref: pushRef(name, missing, repo, where),
  });
  if (path === 'pulls') return method === 'POST' ? { kind: 'pr' } : null;
  if (path === 'releases' || path.startsWith('releases/')) return { kind: 'release' };
  const pull = /^pulls\/([^/]+)\/(.+)$/.exec(path);
  if (pull?.[2] === 'merge') {
    const number = pull[1] ?? '';
    const lookup: readonly string[] | Unlookable =
      where !== 'fixed'
        ? { cannot: where }
        : /^\d+$/.test(number)
          ? [number, ...(repo === null ? [] : ['--repo', repo])]
          : { cannot: 'unnamed' };
    return { kind: 'merge', admin: false, auto: false, lookup };
  }
  if (pull?.[2] === 'update-branch') {
    const number = pull[1] ?? '';
    const unlookable = where === 'elsewhere' || (where === 'beside' && repo === null);
    if (unlookable || !/^\d+$/.test(number)) {
      return {
        kind: 'push',
        ref: asking('the pull request it updates cannot be looked up', false),
      };
    }
    return { kind: 'push', ref: { head: [number, ...(repo === null ? [] : ['--repo', repo])] } };
  }
  if (pull?.[2] === 'reviews' || pull?.[2]?.startsWith('reviews/')) {
    if (unknown('event')) {
      return {
        kind: 'unread',
        why: 'the review event of this `gh api` call is built at run time or read from a file',
        remedy: 'Write the event out with `-f event=…`.',
      };
    }
    return { kind: field('event')?.toUpperCase() === 'APPROVE' ? 'approve' : 'comment' };
  }
  if (/^(pulls|issues)\/[^/]+\/comments(\/|$)|^(pulls|issues)\/comments(\/|$)/.test(path)) {
    return { kind: 'comment' };
  }
  if (path.startsWith('contents/')) {
    return push(field('branch'), 'it names no branch, so it commits to the default branch');
  }
  if (path === 'merges') return push(field('base'), 'its base branch is not written out');
  if (path === 'merge-upstream') {
    return push(field('branch'), 'the branch it updates is not written out');
  }
  if (/^branches\/.+\/rename$/.test(path)) {
    return { kind: 'push', ref: asking('it renames a branch', false) };
  }
  if (path === 'git/refs' && method === 'POST') {
    const ref = field('ref');
    const named = ref === null || ref?.startsWith('refs/') ? ref : undefined;
    return push(named, 'the ref it creates is not written out');
  }
  const ref = /^git\/refs\/(heads|tags)\/(.+)$/.exec(path);
  if (ref) {
    const name = ref[2] ?? '';
    if (ref[1] === 'tags') return { kind: 'push', ref: asking('it pushes a tag', false) };
    if (method === 'DELETE') return { kind: 'push', ref: asking(`it deletes \`${name}\``, false) };
    const force = field('force');
    if (force === null || (force !== undefined && force !== 'false')) {
      return { kind: 'push', ref: asking(`it force-updates \`${name}\``, true) };
    }
    return push(name, '');
  }
  return null;
}

// GraphQL mutations that are ladder steps (GitHub's schema, read 2026-10-03);
// GitHub has none that writes a release. A review approves when its event
// says APPROVE.
const BY_ID = {
  kind: 'merge',
  admin: false,
  auto: false,
  lookup: { cannot: 'unnamed' },
} as const satisfies GhAction;
const MUTATIONS: Record<string, GhAction | 'review' | 'ref' | 'update'> = {
  createPullRequest: { kind: 'pr' },
  markPullRequestReadyForReview: { kind: 'pr' },
  revertPullRequest: { kind: 'pr' },
  mergePullRequest: BY_ID,
  enablePullRequestAutoMerge: { ...BY_ID, auto: true },
  enqueuePullRequest: BY_ID,
  addPullRequestReview: 'review',
  submitPullRequestReview: 'review',
  updatePullRequestBranch: 'update',
  ...Object.fromEntries(
    [
      'addComment',
      'addPullRequestReviewComment',
      'addPullRequestReviewThread',
      'addPullRequestReviewThreadReply',
      'updateIssueComment',
      'updatePullRequestReview',
      'updatePullRequestReviewComment',
      'deleteIssueComment',
      'deletePullRequestReview',
      'deletePullRequestReviewComment',
      'dismissPullRequestReview',
      'resolveReviewThread',
      'unresolveReviewThread',
      'minimizeComment',
      'unminimizeComment',
    ].map((name) => [name, { kind: 'comment' } as const]),
  ),
  ...Object.fromEntries(
    [
      'createCommitOnBranch',
      'createLinkedBranch',
      'createRef',
      'updateRef',
      'updateRefs',
      'deleteRef',
      'mergeBranch',
    ].map((name) => [name, 'ref' as const]),
  ),
};

const unreadEvent: GhAction = {
  kind: 'unread',
  why: 'the review event of this GraphQL mutation is built at run time or read from a file',
  remedy: 'Write the event out.',
};

const approves = (v: string | null | undefined) => v?.toUpperCase() === 'APPROVE';

// A review approves only by its `event` argument, written in the query or
// passed in a variable (`-f event=…`, `-f input[event]=…`).
function reviewOf(query: string, call: ApiCall): GhAction {
  // Every review in the query counts, so one that approves is never read as a
  // comment. `(?<!\$)` skips a variable's definition (`$event: …Event`).
  const args = [...query.matchAll(/(?<!\$)\bevent\s*:\s*(\$?\w+)/g)].map((m) => m[1] ?? '');
  // A variable no field sets takes its default; a declared one with neither
  // sends no event (a pending review), and an undeclared one is unread.
  const values = args.map((arg) => {
    if (!arg.startsWith('$')) return arg;
    const name = arg.slice(1);
    if (call.fields.has(name)) return call.fields.get(name);
    const declared = new RegExp(String.raw`\$${name}\s*:\s*[^,)=$]*(?:=\s*(\w+))?`).exec(query);
    return declared === null ? null : (declared[1] ?? '');
  });
  const keys = [...call.fields.keys()].filter((k) => /(^|\[)event\]?$/.test(k));
  if (values.some((v) => approves(v)) || keys.some((k) => approves(call.fields.get(k)))) {
    return { kind: 'approve' };
  }
  if (values.includes(null)) return unreadEvent;
  // A review given a whole input object (`input: $input`) carries its event in
  // that variable or its `[event]` key, either of which may be read at run time.
  const objects = [...query.matchAll(/\binput\s*:\s*\$(\w+)/g)].map((m) => m[1]);
  const hidden = [...call.fields].some(
    ([k, v]) => v === null && objects.some((o) => k === o || k === `${o}[event]`),
  );
  return hidden ? unreadEvent : { kind: 'comment' };
}

// The query with its strings and comments blanked, so text inside them names
// no operation or mutation.
const bare = (query: string) =>
  query.replaceAll(/"""(?:\\"""|[\s\S])*?"""|"(?:\\.|[^"\\])*"|#[^\n]*/g, ' ');

function graphqlActions(call: ApiCall): GhAction[] {
  const query = call.unnamed || call.input ? null : call.fields.get('query');
  if (query === undefined) return [];
  if (query === null) {
    return [
      {
        kind: 'unread',
        why: 'the GraphQL query of this `gh api` call is built at run time or read from a file',
        remedy: 'Write the query out with `-f query=…`.',
      },
    ];
  }
  const ops = bare(query);
  if (!/(^|[\s}])mutation\b/.test(ops)) return [];
  const found: GhAction[] = [];
  for (const [name, action] of Object.entries(MUTATIONS)) {
    if (!new RegExp(String.raw`\b${name}\s*\(`).test(ops)) continue;
    if (action === 'review') found.push(reviewOf(ops, call));
    else if (action === 'ref') {
      // `force: $f` reads the field that sets `$f`.
      const forced = (value: string | undefined) => {
        const name = /^\$(\w+)$/.exec(value ?? '')?.[1];
        const set = name === undefined ? value : call.fields.get(name);
        return set !== 'false';
      };
      const force =
        [...ops.matchAll(/\bforce\s*:\s*(\$?\w+)/g)].some((m) => forced(m[1])) ||
        [...call.fields].some(([k, v]) => /(^|\[)force\]?$/.test(k) && v !== 'false');
      const asks = 'the gate does not read which branch a GraphQL mutation writes';
      found.push({ kind: 'push', ref: asking(asks, force) });
    } else if (action === 'update') {
      // A rebase rewrites the branch, as `gh pr update-branch --rebase` does.
      const method = (value: string | undefined) => {
        const name = /^\$(\w+)$/.exec(value ?? '')?.[1];
        return name === undefined ? value : call.fields.get(name);
      };
      const rebases =
        [...ops.matchAll(/\bupdateMethod\s*:\s*(\$?\w+)/g)].some((m) => method(m[1]) !== 'MERGE') ||
        [...call.fields].some(([k, v]) => /(^|\[)updateMethod\]?$/.test(k) && v !== 'MERGE');
      const asks = 'it names the pull request whose branch it updates by id';
      found.push({ kind: 'push', ref: asking(asks, rebases) });
    } else found.push(action);
  }
  return found;
}

// What a `gh api` call writes on the ladder, from the words after `api`. A
// read, or a write to an endpoint no ladder step covers, is nothing.
export function apiActions(words: Word[], context: GhContext, fed: boolean): GhAction[] {
  const call = readApi(words);
  if (call.method === 'GET' || call.method === 'HEAD') return [];
  if (call.opaque || call.method === '?') {
    return [
      {
        kind: 'unread',
        why: 'the arguments of `gh api` are built at run time',
        remedy: 'Write its options out; a read can name `--method GET`.',
      },
    ];
  }
  if (call.endpoint === null) {
    return fed ? [{ kind: 'unread', why: 'its `gh api` endpoint comes from its input' }] : [];
  }
  // As gh's api.go decides it: POST once fields or --input are given.
  const written = call.fields.size > 0 || call.input || call.unnamed;
  const method = call.method ?? (written ? 'POST' : 'GET');
  if (method === 'GET' || method === 'HEAD') return [];
  if (fed) return [{ kind: 'unread', why: 'the arguments of `gh api` come from its input' }];
  if (call.endpoint.dynamic) {
    return [
      {
        kind: 'unread',
        why: 'the endpoint of this `gh api` write is built at run time',
        remedy: 'Write the endpoint out.',
      },
    ];
  }
  // gh sends a full URL as written: another host is another repository.
  // GitHub Enterprise serves REST under /api/v3/ and GraphQL at /api/graphql.
  const url = /^https?:\/\/([^/]+)\/(?:api\/v3\/|api\/(?=graphql\b))?/i.exec(call.endpoint.text);
  const host = url !== null && url[1]?.toLowerCase() !== 'api.github.com';
  const endpoint = call.endpoint.text
    .slice(url?.[0].length ?? 0)
    .replace(/^\//, '')
    .replace(/\?.*$/, '');
  if (endpoint === 'graphql') return graphqlActions(call);
  const m = /^repos\/([^/]+)\/([^/]+)\/(.+)$/.exec(endpoint);
  if (!m) return [];
  const [owner = '', name = '', path = ''] = m.slice(1);
  const placeholder = owner === '{owner}' && name === '{repo}';
  const elsewhere =
    context === 'elsewhere' || call.hostname || host || (!placeholder && /[{}]/.test(owner + name));
  const where = elsewhere ? 'elsewhere' : context;
  const action = restAction(method, path, placeholder ? null : `${owner}/${name}`, call, where);
  return action === null ? [] : [action];
}

// The GitHub MCP server's write tools that are ladder steps (its README,
// read 2026-10-03), matched by name under any server name. It has no tool
// that writes a release.
const MCP_COMMENT = new Set([
  'add_comment_to_pending_review',
  'add_reply_to_pull_request_comment',
  'add_issue_comment',
  'update_issue_comment',
]);
const MCP_PUSH = new Set(['push_files', 'create_or_update_file', 'delete_file', 'create_branch']);
const MCP_TOOLS = [
  'create_pull_request',
  'create_pull_request_with_copilot',
  'merge_pull_request',
  'pull_request_review_write',
  'update_pull_request_branch',
  'update_pull_request',
  ...MCP_COMMENT,
  ...MCP_PUSH,
];

// Matches the tool names mcpAction reads.
export const MCP_GITHUB = new RegExp(String.raw`^mcp__.+__(${MCP_TOOLS.join('|')})$`);

// The arguments a refusal quotes: those naming where the write goes.
const SHOWN = new Set([
  'owner',
  'repo',
  'pullNumber',
  'issue_number',
  'comment_id',
  'commentId',
  'branch',
  'from_branch',
  'base',
  'head',
  'path',
  'method',
  'event',
  'merge_method',
]);

// The tool call as a refusal quotes it: its name and the arguments naming
// where it writes, with characters that could hide or reorder text replaced.
export function shownCall(tool: string, input: Record<string, unknown>): string {
  const args = Object.entries(input).filter(
    ([key, v]) => SHOWN.has(key) && ['string', 'number', 'boolean'].includes(typeof v),
  );
  const shown = `${tool} ${JSON.stringify(Object.fromEntries(args))}`;
  return shown.replaceAll(/[\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/gu, '\u{FFFD}');
}

const text = (v: unknown) => (typeof v === 'string' || typeof v === 'number' ? String(v) : null);
// An owner or repository name gh reads as one, never as an option.
const named = (s: string | null): s is string => s !== null && /^\w[\w.-]*$/.test(s);

// What a GitHub MCP tool call is on the ladder, or null for any other tool.
export function mcpAction(tool: string, input: Record<string, unknown>): GhAction | null {
  const name = MCP_TOOLS.find((t) => tool.endsWith(`__${t}`));
  if (name === undefined) return null;
  const owner = text(input.owner);
  const repoName = text(input.repo);
  const repo = named(owner) && named(repoName) ? `${owner}/${repoName}` : null;
  if (name === 'create_pull_request' || name === 'create_pull_request_with_copilot') {
    return { kind: 'pr' };
  }
  if (name === 'merge_pull_request') {
    const number = text(input.pullNumber);
    const lookup =
      number !== null && /^\d+$/.test(number) && repo !== null
        ? [number, '--repo', repo]
        : { cannot: 'unnamed' as const };
    return { kind: 'merge', admin: false, auto: false, lookup };
  }
  if (name === 'pull_request_review_write') {
    return { kind: text(input.event)?.toUpperCase() === 'APPROVE' ? 'approve' : 'comment' };
  }
  if (name === 'update_pull_request_branch') {
    const number = text(input.pullNumber);
    if (number === null || !/^\d+$/.test(number) || repo === null) {
      return {
        kind: 'push',
        ref: asking('the pull request it updates cannot be looked up', false),
      };
    }
    return { kind: 'push', ref: { head: [number, '--repo', repo] } };
  }
  // Marking a draft ready for review is the pull request step; other edits are not.
  if (name === 'update_pull_request') {
    return input.draft === false || input.draft === 'false' ? { kind: 'pr' } : null;
  }
  if (MCP_COMMENT.has(name)) return { kind: 'comment' };
  // gh's lookup of the default branch needs the repository spelled out.
  if (repo === null) return { kind: 'push', ref: asking('it does not name its repository', false) };
  const branch = branchOf(text(input.branch) ?? undefined, 'it names no branch');
  return { kind: 'push', ref: typeof branch === 'string' ? { branch, repo } : branch };
}

files.hooks/ladder.ts:
// Where the agent stops to ask the user before an outward step. Pure.
//
// One setting, review-cycle's `stopBefore`: a step below the chosen rung runs
// without asking, one at or above it needs the user's request. Claude Code
// passes the register options only from user and managed settings, so the
// gate reads the project's and the local file's pluginConfigs itself.

export const RUNGS = ['commit', 'push', 'open PR', 'merge', 'release', 'never stop'] as const;
export type StopBefore = (typeof RUNGS)[number];
export const DEFAULT_STOP: StopBefore = 'push';
// What a setting the gate cannot trust falls back to.
export const STRICTEST: StopBefore = RUNGS[0];

// The steps the gate judges, in rung order.
export type Step = 'commit' | 'push' | 'pr' | 'merge' | 'approve' | 'release';
const STEP_RUNG: Record<Step, StopBefore> = {
  commit: 'commit',
  push: 'push',
  pr: 'open PR',
  merge: 'merge',
  // An approval can be all a merge waits for.
  approve: 'merge',
  release: 'release',
};

export type Source = 'default' | 'user' | 'project' | 'local';
export type Ladder = Readonly<{ stopBefore: StopBefore; source: Source }>;

const PLUGIN = /^review-cycle(@|$)/;

const rank = (r: StopBefore): number => RUNGS.indexOf(r);

// A value outside the options counts as unset, as Claude Code documents for
// the options it passes.
export function stopBeforeOf(value: unknown): StopBefore | null {
  return RUNGS.find((r) => r === value) ?? null;
}

// The value a settings file's pluginConfigs gives review-cycle, under its bare
// name or a marketplace-qualified one (`review-cycle@oakoss`). A value outside
// the options stops before every step: a typo meant to stop earlier must not
// leave a looser rung in force.
export function configured(pluginConfigs: unknown): StopBefore | null {
  if (pluginConfigs === null || typeof pluginConfigs !== 'object') return null;
  let found: StopBefore | null = null;
  for (const [name, entry] of Object.entries(pluginConfigs)) {
    if (!PLUGIN.test(name) || entry === null || typeof entry !== 'object') continue;
    const options: unknown = (entry as { options?: unknown }).options;
    if (options === null || typeof options !== 'object' || !('stopBefore' in options)) continue;
    const value = stopBeforeOf(options.stopBefore) ?? STRICTEST;
    if (found === null || rank(value) < rank(found)) found = value;
  }
  return found;
}

// The local file is the user's own and gitignored, so it may set any rung. A
// committed project file only stops earlier than the user's own value.
export function effective(
  user: StopBefore | null,
  project: StopBefore | null,
  local: StopBefore | null,
): Ladder {
  if (local !== null) return { stopBefore: local, source: 'local' };
  // Claude Code fills in the option's default, so a user value equal to it
  // cannot be told from no value at all.
  const mine: Ladder =
    user === null || user === DEFAULT_STOP
      ? { stopBefore: DEFAULT_STOP, source: 'default' }
      : { stopBefore: user, source: 'user' };
  if (project !== null && rank(project) < rank(mine.stopBefore)) {
    return { stopBefore: project, source: 'project' };
  }
  return mine;
}

// Whether the step needs the user's request under this ladder.
export function asks(ladder: Ladder, step: Step): boolean {
  return rank(STEP_RUNG[step]) >= rank(ladder.stopBefore);
}

export function where(source: Source): string {
  if (source === 'default') return 'the default';
  if (source === 'project') return '.claude/settings.json';
  if (source === 'local') return '.claude/settings.local.json';
  return '/config';
}

files.hooks/ledger.ts:
// The findings ledger: what earlier review cycles in a repository settled
// without fixing, carried into the next cycle's briefs so reviewers do not
// re-litigate it. Pure.
//
// A fixed finding is never an entry: the code changed, so raising it again
// means it came back. An entry leaves the ledger when a cycle resolves it, when
// its file is gone, or when newer entries push it past the cap. One settled
// longer ago than EXPIRY_DAYS reads as stale, so a cycle judges it again.

export const KINDS = ['deferred', 'rebutted', 'left-alone', 'question'] as const;
export type Kind = (typeof KINDS)[number];

export type Entry = {
  id: string;
  path: string;
  line: number | null;
  kind: Kind;
  finding: string;
  reason: string;
  source: string;
  // The path's blob in the working tree the latest cycle to carry it reviewed,
  // so a reader can tell whether the file changed since.
  blob: string;
  // When a cycle last settled it; carrying it forward does not move this.
  date: string;
};

export type NewEntry = Omit<Entry, 'id' | 'blob' | 'date'>;

// One repository's ledger as read. `unreadable` counts what this version could
// not write back unchanged, such as entries a newer version wrote; the next
// record drops them and says how many.
export type Stored = { entries: Entry[]; unreadable: number; updated: number };

// The store holds MAX_REPOS ledgers in 4 MiB of JSON. A byte budget, not an
// entry count: entries run near 470 bytes but can reach about 10 KB.
export const MAX_LEDGER_BYTES = 384 * 1024;
export const MAX_TEXT = 400;
export const MAX_PATH = 1024;
export const MAX_REPOS = 10;
export const EXPIRY_DAYS = 90;
export const PREFIX = 'ledger:';

const ENTRY_KEYS = [
  'id',
  'path',
  'line',
  'kind',
  'finding',
  'reason',
  'source',
  'blob',
  'date',
] as const;
const BLOB = /^([0-9a-f]{40}|[0-9a-f]{64})$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The store refuses a key over 256 characters.
export const MAX_KEY = 256;

// FNV-1a from `basis`, as 8 hex digits.
function fnv(text: string, basis: number): string {
  let h = basis;
  for (const ch of text) {
    h ^= ch.codePointAt(0) ?? 0;
    h = Math.imul(h, 0x01_00_01_93) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

// A path too long for the store is keyed by its hash. `common` is absolute, so
// a hashed key (`#`) never equals a path's own.
export function keyOf(common: string): string {
  const key = `${PREFIX}${common}`;
  if (key.length <= MAX_KEY) return key;
  return `${PREFIX}#${fnv(common, 0x81_1c_9d_c5)}${fnv(common, 0x05_0c_5d_1f)}`;
}

// The same finding at the same path gets the same id in every cycle.
export function entryId(path: string, finding: string): string {
  return fnv(`${path}\0${finding}`, 0x81_1c_9d_c5);
}

// Never cuts a surrogate pair in half.
function clip(s: string): string {
  const t = s.trim().replaceAll(/\s+/g, ' ');
  if (t.length <= MAX_TEXT) return t;
  const head = t.slice(0, MAX_TEXT - 1);
  return `${/[\uD800-\uDBFF]$/.test(head) ? head.slice(0, -1) : head}…`;
}

function isKind(k: unknown): k is Kind {
  return typeof k === 'string' && (KINDS as readonly string[]).includes(k);
}

function text(v: unknown): string | null {
  return typeof v === 'string' && v.trim() !== '' ? v : null;
}

function normalPath(p: string): string {
  return p.trim().replace(/^(\.\/)+/, '');
}

// A path as git's changed-path list spells it, or why it is not one: Phase 3
// selects entries by that list, so any other spelling is never read back.
function pathOf(v: unknown): string | { error: string } {
  if (typeof v !== 'string') return { error: 'path is required' };
  if (/\p{Cc}/u.test(v)) return { error: 'path holds a control character' };
  const p = normalPath(v);
  if (p === '') return { error: 'path is empty' };
  if (p.length > MAX_PATH) return { error: `path is over ${MAX_PATH} characters` };
  // Normalizing again must change nothing, or the stored path reads back as
  // another one.
  if (normalPath(p) !== p) return { error: `path starts or ends with whitespace: ${p}` };
  const segments = p.split(/[/\\]/);
  if (/^[A-Za-z]:/.test(p) || segments.some((s) => s === '' || s === '.' || s === '..')) {
    return { error: `path must be repository-relative, as git spells it: ${p}` };
  }
  return p;
}

// One finding as the record tool takes it, or its first fault.
function newEntryOf(raw: unknown): NewEntry | { error: string } {
  const e = (raw ?? {}) as Record<string, unknown>;
  if (e.kind === 'fixed') {
    return {
      error:
        'a fixed finding is not recorded; pass the id of the entry it settled in `resolve` instead',
    };
  }
  if (!isKind(e.kind)) return { error: `kind must be one of ${KINDS.join(', ')}` };
  const path = pathOf(e.path);
  if (typeof path !== 'string') return path;
  const finding = text(e.finding);
  const reason = text(e.reason);
  const source = text(e.source);
  if (!finding || !reason || !source) {
    return { error: 'finding, reason and source are all required' };
  }
  const line = e.line ?? null;
  if (line !== null && !(Number.isSafeInteger(line) && (line as number) > 0)) {
    return { error: 'line must be a positive integer' };
  }
  return {
    path,
    line: line as number | null,
    kind: e.kind,
    finding: clip(finding),
    reason: clip(reason),
    source: clip(source),
  };
}

// A stored entry, or null unless this version would write it back exactly as
// stored: every key known, every value one the record tool produces.
function storedEntryOf(raw: unknown): Entry | null {
  if (typeof raw !== 'object' || raw === null) return null;
  const r = raw as Record<string, unknown>;
  if (Object.keys(r).some((k) => !(ENTRY_KEYS as readonly string[]).includes(k))) return null;
  const n = newEntryOf(r);
  if ('error' in n) return null;
  const { blob, date } = r;
  if (typeof blob !== 'string' || !BLOB.test(blob)) return null;
  if (typeof date !== 'string' || !DATE.test(date)) return null;
  const e: Entry = { id: entryId(n.path, n.finding), ...n, blob, date };
  return ENTRY_KEYS.every((k) => e[k] === r[k]) ? e : null;
}

// The `updated` stamp of any stored value, ledger or not, so pruning orders a
// ledger this version cannot read by when it was written.
export function updatedOf(value: unknown): number {
  const u = (value as { updated?: unknown } | null | undefined)?.updated;
  return typeof u === 'number' ? u : 0;
}

// Whatever the store holds under one repository's key.
export function storedOf(value?: unknown): Stored {
  if (value === undefined) return { entries: [], unreadable: 0, updated: 0 };
  const updated = updatedOf(value);
  const v = (value ?? {}) as { entries?: unknown; updated?: unknown };
  const known = new Set(['entries', 'updated']);
  if (
    typeof value !== 'object' ||
    value === null ||
    !Array.isArray(v.entries) ||
    typeof v.updated !== 'number' ||
    Object.keys(value).some((k) => !known.has(k))
  ) {
    // Every entry is lost with the ledger around it, so each one counts.
    const lost = Array.isArray(v.entries) ? v.entries.length : 0;
    return { entries: [], unreadable: Math.max(1, lost), updated };
  }
  const entries: Entry[] = [];
  const ids = new Set<string>();
  let unreadable = 0;
  for (const raw of v.entries) {
    const e = storedEntryOf(raw);
    if (e && !ids.has(e.id)) {
      ids.add(e.id);
      entries.push(e);
    } else {
      unreadable++;
    }
  }
  return { entries, unreadable, updated };
}

// `keep` carries entries a cycle settled again unchanged: each is stamped with
// its file as that cycle reviewed it, and its date stays.
export type Recording = { add: NewEntry[]; resolve: string[]; keep: string[] };

function ids(v: unknown): v is string[] {
  return Array.isArray(v) && v.every((r) => typeof r === 'string' && /^[0-9a-f]{8}$/.test(r));
}

// The record tool's input, whole or not at all: a batch half-written is
// harder to read back than one refused with its first fault named.
export function parseRecord(input: unknown): Recording | { error: string } {
  const i = (input ?? {}) as { entries?: unknown; resolve?: unknown; keep?: unknown };
  const rawEntries = i.entries ?? [];
  const rawResolve = i.resolve ?? [];
  const rawKeep = i.keep ?? [];
  if (!Array.isArray(rawEntries)) return { error: '`entries` must be an array' };
  if (!ids(rawResolve)) return { error: '`resolve` must be an array of entry ids' };
  if (!ids(rawKeep)) return { error: '`keep` must be an array of entry ids' };
  const add: NewEntry[] = [];
  for (const [n, raw] of rawEntries.entries()) {
    const e = newEntryOf(raw);
    if ('error' in e) return { error: `entries[${n}]: ${e.error}` };
    add.push(e);
  }
  if (add.length === 0 && rawResolve.length === 0 && rawKeep.length === 0) {
    return { error: 'nothing to record: pass `entries`, `keep` or `resolve`' };
  }
  return { add, resolve: rawResolve, keep: rawKeep };
}

export type Merged = {
  entries: Entry[];
  added: number;
  updated: number;
  resolved: number;
  kept: number;
  // Kept entries whose file is gone from the working tree, and so dropped.
  gone: number;
  // Ids in `resolve` or `keep` that named no entry.
  unknown: string[];
  evicted: number;
};

// Resolves first, then keeps, then adds, so a batch that resolves an entry and
// records the same finding again keeps the new one. A kept or re-recorded
// entry moves to the newest end, so eviction takes what no cycle has touched
// longest. `blobs` must hold every added path; a kept entry whose path it
// lacks is gone.
export function merge(
  existing: Entry[],
  rec: Recording,
  blobs: ReadonlyMap<string, string>,
  date: string,
): Merged {
  const byId = new Map(existing.map((e) => [e.id, e]));
  const unknown: string[] = [];
  let resolved = 0;
  for (const id of rec.resolve) {
    if (byId.delete(id)) resolved++;
    else unknown.push(id);
  }
  let kept = 0;
  let gone = 0;
  for (const id of rec.keep) {
    const e = byId.get(id);
    if (!e) {
      unknown.push(id);
      continue;
    }
    byId.delete(id);
    const blob = blobs.get(e.path);
    if (blob === undefined) {
      gone++;
    } else {
      byId.set(id, { ...e, blob });
      kept++;
    }
  }
  let added = 0;
  let updated = 0;
  for (const n of rec.add) {
    const blob = blobs.get(n.path);
    if (blob === undefined) throw new Error(`no blob for ${n.path}`);
    const id = entryId(n.path, n.finding);
    if (byId.delete(id)) updated++;
    else added++;
    byId.set(id, { id, ...n, blob, date });
  }
  const all = [...byId.values()];
  const sizes = all.map((e) => utf8Bytes(JSON.stringify(e)) + 1);
  let size = sizes.reduce((n, s) => n + s, 0);
  let evicted = 0;
  while (evicted < all.length && size > MAX_LEDGER_BYTES) size -= sizes[evicted++] ?? 0;
  return { entries: all.slice(evicted), added, updated, resolved, kept, gone, unknown, evicted };
}

export function utf8Bytes(s: string): number {
  let n = 0;
  for (const ch of s) {
    const c = ch.codePointAt(0) ?? 0;
    n += c < 0x80 ? 1 : c < 0x8_00 ? 2 : c < 0x1_00_00 ? 3 : 4;
  }
  return n;
}

export function isStale(date: string, now: number): boolean {
  const [y, m, d] = date.split('-').map(Number);
  return now - Date.UTC(y ?? 0, (m ?? 1) - 1, d ?? 1) > EXPIRY_DAYS * 86_400_000;
}

export function select(entries: Entry[], paths?: readonly string[]): Entry[] {
  if (paths === undefined) return entries;
  const want = new Set(paths.map((p) => normalPath(p)));
  return entries.filter((e) => want.has(e.path));
}

// `git ls-tree -r -z` output as path to blob id.
export function blobsOf(lsTree: string): Map<string, string> {
  const blobs = new Map<string, string>();
  for (const rec of lsTree.split('\0')) {
    const m = /^\d+ blob ([0-9a-f]+)\t(.+)$/s.exec(rec);
    if (m?.[1] && m[2]) blobs.set(m[2], m[1]);
  }
  return blobs;
}

// The other repositories' ledgers to drop so that, with this one, the store
// holds at most MAX_REPOS: the least recently updated go first.
export function staleKeys(
  ledgers: readonly { key: string; updated: number }[],
  keep: string,
): string[] {
  const others = ledgers.filter((l) => l.key !== keep).toSorted((a, b) => a.updated - b.updated);
  return others.slice(0, Math.max(0, others.length - (MAX_REPOS - 1))).map((l) => l.key);
}

files.hooks/ledger-store.ts:
// Reading and recording the findings ledger against the plugin's store. The
// store and the working tree come in as parameters, so this runs under plain
// tests; register.ts binds them to `$`.

import { firstLine, worktreeTree, type Git } from './git';
import {
  blobsOf,
  isStale,
  keyOf,
  merge,
  PREFIX,
  select,
  staleKeys,
  storedOf,
  updatedOf,
  type Recording,
} from './ledger';

export type Store = {
  get: (key: string) => Promise<unknown>;
  set: (key: string, value: unknown) => Promise<void>;
  keys: () => Promise<string[]>;
  delete: (key: string) => Promise<void>;
};

// Each path's blob in the working tree as it stands, keyed by path.
export type Blobs = (paths: string[]) => Promise<Map<string, string>>;

// Literal pathspecs, so a path that starts with `:` or holds `*` names only
// itself.
export async function blobsAt(
  git: Git,
  top: string,
  paths: string[],
): Promise<Map<string, string>> {
  if (paths.length === 0) return new Map();
  const tree = await worktreeTree(git, top);
  const r = await git(['git', '--literal-pathspecs', 'ls-tree', '-r', '-z', tree, '--', ...paths], {
    cwd: top,
  });
  if (r.exitCode !== 0) {
    throw new Error(`git ls-tree failed: ${firstLine(r.stderr) || `exit ${r.exitCode}`}`);
  }
  return blobsOf(r.stdout);
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

// The entries for `paths`, each with the file as it stands now and whether it
// changed or went stale since a cycle settled it.
export async function readLedger(
  store: Store,
  blobs: Blobs,
  common: string,
  paths: readonly string[] | undefined,
  now: number,
): Promise<Record<string, unknown>> {
  const stored = storedOf(await store.get(keyOf(common)));
  const shown = select(stored.entries, paths);
  const status: Record<string, unknown> = {
    total: stored.entries.length,
    unreadable: stored.unreadable,
  };
  let current: Map<string, string> | null = null;
  try {
    current = await blobs([...new Set(shown.map((e) => e.path))]);
  } catch (error) {
    status.note = `changed is null: the working tree could not be read (${messageOf(error)})`;
  }
  status.entries = shown.map((e) => {
    const file = current ? (current.get(e.path) ?? null) : null;
    return {
      ...e,
      current: file,
      changed: current ? file !== e.blob : null,
      stale: isStale(e.date, now),
    };
  });
  return status;
}

// Records `rec` and returns the tool's answer. Throws when the store or the
// working tree cannot be read, having written nothing.
export async function recordInto(
  store: Store,
  blobs: Blobs,
  common: string,
  rec: Recording,
  now: number,
): Promise<string> {
  const key = keyOf(common);
  const stored = storedOf(await store.get(key));
  const kept = new Set(rec.keep);
  const paths = [
    ...new Set([
      ...rec.add.map((n) => n.path),
      ...stored.entries.filter((e) => kept.has(e.id)).map((e) => e.path),
    ]),
  ];
  const found = await blobs(paths);
  const absent = [...new Set(rec.add.map((n) => n.path))].filter((p) => !found.has(p));
  if (absent.length > 0) {
    return `review-cycle ledger: nothing recorded: not a file in the working tree: ${absent.join(', ')}`;
  }
  const status: Record<string, unknown> = {};
  // Before the write, so a store too full to take it has room made first.
  try {
    const all = await store.keys();
    const ledgers = await Promise.all(
      all
        .filter((k) => k.startsWith(PREFIX))
        .map(async (k) => {
          const value = await store.get(k);
          return { key: k, updated: updatedOf(value) };
        }),
    );
    for (const stale of staleKeys(ledgers, key)) await store.delete(stale);
  } catch (error) {
    status.note = `older repositories' ledgers could not be pruned: ${messageOf(error)}`;
  }
  const m = merge(stored.entries, rec, found, new Date(now).toISOString().slice(0, 10));
  await store.set(key, { entries: m.entries, updated: now });
  const { entries, ...counts } = m;
  return JSON.stringify(
    {
      ...counts,
      total: entries.length,
      ...(stored.unreadable > 0 ? { dropped: stored.unreadable } : {}),
      ...status,
    },
    null,
    2,
  );
}

files.hooks/nudge.ts:
// Whether the gate nudges the agent to review at the end of a turn. Pure.

const PLUGIN = /^review-cycle(@|$)/;

// A value that is not a boolean sets nothing. Off wins between a bare and a
// marketplace-qualified entry.
export function nudgeOf(pluginConfigs: unknown): boolean | null {
  if (pluginConfigs === null || typeof pluginConfigs !== 'object') return null;
  let found: boolean | null = null;
  for (const [name, entry] of Object.entries(pluginConfigs)) {
    if (!PLUGIN.test(name) || entry === null || typeof entry !== 'object') continue;
    const options: unknown = (entry as { options?: unknown }).options;
    if (options === null || typeof options !== 'object' || !('nudge' in options)) continue;
    if (typeof options.nudge !== 'boolean') continue;
    found = found === false ? false : options.nudge;
  }
  return found;
}

// The local file is the user's own, so it decides; a committed project file
// can only turn the nudge off.
export function nudgeOn(user: boolean, project: boolean | null, local: boolean | null): boolean {
  if (local !== null) return local;
  return user && project !== false;
}

// A turn that ends by asking the user is waiting on their answer.
export function asksUser(answer: string): boolean {
  return answer.replace(/[\s*_]+$/, '').endsWith('?');
}

files.hooks/push-verdict.ts:
// Whether the user's request covers a push the gate is judging. Pure.

import { covers, type Grant, type PushLevel } from './consent';
import type { PushSpec } from './git-args';

export type Needed = Exclude<PushLevel, 'none'>;

// A bare force needs a bare-force request, a lease a force request, and any
// other push a push request.
export function neededFor(spec: PushSpec): Needed {
  return spec.force === 'none' ? 'push' : spec.force;
}

// One remote ref a `git push --dry-run --porcelain` would update: its flag
// (` ` fast-forward, `+` forced, `-` deleted, `*` new, `!` rejected, `=` up
// to date), the full destination ref, and the URL of the remote.
export type DryRunRef = { flag: string; to: string; url: string };

export function parseDryRun(stdout: string): DryRunRef[] {
  const refs: DryRunRef[] = [];
  let url = '';
  for (const line of stdout.split('\n')) {
    if (line.startsWith('To ')) {
      url = line.slice(3).trim();
      continue;
    }
    const m = /^(.)\t([^\t]*)\t/.exec(line);
    if (!m) continue;
    const [, flag = '', refspec = ''] = m;
    refs.push({ flag, to: refspec.slice(refspec.indexOf(':') + 1), url });
  }
  return refs;
}

// A remote's default branch, or why it could not be read.
export type DefaultBranch = { branch: string } | { unreadable: string };

// Why a push asks whatever the setting, from the refs git says it updates and
// each remote's default branch. An up-to-date ref still counts: a commit in
// the same command lands before the push but after the dry run.
export function askingReason(
  refs: readonly DryRunRef[],
  defaults: ReadonlyMap<string, DefaultBranch>,
): string | null {
  // A quiet push prints no ref lines, so none read is not none pushed.
  if (refs.length === 0) return 'its dry run named no ref it would update';
  for (const { flag, to, url } of refs) {
    const name = to.replace(/^refs\/(heads|tags)\//, '');
    if (flag === '-') return `it deletes \`${name}\``;
    if (flag === '+') return `it force-updates \`${name}\``;
    if (to.startsWith('refs/tags/')) return `it pushes the tag \`${name}\``;
    const head = defaults.get(url) ?? { unreadable: 'not read' };
    if ('unreadable' in head) {
      return `the default branch of ${url} could not be read (${head.unreadable})`;
    }
    if (to === `refs/heads/${head.branch}`) {
      return `it pushes to \`${head.branch}\`, the default branch`;
    }
  }
  return null;
}

// The level the push needs and the grant falls short of; null when covered.
export function unasked(spec: PushSpec, grant: Grant): Needed | null {
  const needed = neededFor(spec);
  return covers(grant, needed) ? null : needed;
}

// What a push may do, git's or GitHub's: run when the grant covers it, run
// unasked when something lets a plain push through and nothing makes it ask,
// or be refused for the level it is missing. `alwaysAsks` runs only for a
// push something would let through.
export type PushOutcome =
  | { kind: 'covered' }
  | { kind: 'unasked' }
  | { kind: 'refused'; missing: 'push'; always: string | null }
  | { kind: 'refused'; missing: Exclude<Needed, 'push'>; always: null };

export async function pushOutcome(
  missing: Needed | null,
  letsThrough: boolean,
  alwaysAsks: () => Promise<string | null>,
): Promise<PushOutcome> {
  if (missing === null) return { kind: 'covered' };
  if (missing !== 'push') return { kind: 'refused', missing, always: null };
  const always = letsThrough ? await alwaysAsks() : null;
  if (letsThrough && always === null) return { kind: 'unasked' };
  return { kind: 'refused', missing, always };
}

files.hooks/settings.ts:
// Decides whether a change to a settings file switches or configures
// review-cycle. Pure.
//
// Claude Code reloads a plugin when user settings change, so an agent that
// edits `enabledPlugins` or `pluginConfigs` mid-session turns the gate off or
// loosens it without passing through `config.set`. Any JSON file counts,
// because a settings file can be passed with `--settings` under any name.

import { parse, type Statement, type Word } from './shell';

const PLUGIN = /^review-cycle(@|$)/;
const SWITCHES = ['enabledPlugins', 'pluginConfigs'] as const;
// The key outside the plugin tables that stops every installed mod loading.
const HOOKS_OFF = 'disableAllHooks';

// Every line of text naming a switch, for files that do not parse even with
// comments and trailing commas removed.
const SWITCH_TEXT = /"(enabledPlugins|pluginConfigs|disableAllHooks|review-cycle[^"]*)"[^\n]*/g;

export function isJsonPath(path: string): boolean {
  return /\.json[c5]?$/i.test(path);
}

function objectOf(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

// The text as JSON, with what Claude Code also accepts removed: a byte-order
// mark, comments and trailing commas. Strings are copied untouched.
function strictJson(text: string): string {
  let out = '';
  let i = text.startsWith(String.fromCodePoint(0xfe_ff)) ? 1 : 0;
  while (i < text.length) {
    const c = text[i] ?? '';
    if (c === '"') {
      const end = /^"(?:[^"\\]|\\.)*"/s.exec(text.slice(i))?.[0] ?? text.slice(i);
      out += end;
      i += end.length;
    } else if (text.startsWith('//', i)) {
      const nl = text.indexOf('\n', i);
      i = nl === -1 ? text.length : nl;
    } else if (text.startsWith('/*', i)) {
      const close = text.indexOf('*/', i + 2);
      i = close === -1 ? text.length : close + 2;
    } else {
      if (c === '}' || c === ']') out = out.replace(/,\s*$/, '');
      out += c;
      i++;
    }
  }
  return out;
}

// Everything in the text that switches the gate, as comparable text. null
// when the text is not a JSON object.
function gateEntries(text: string): string | null {
  let parsed: Record<string, unknown> | null;
  try {
    parsed = objectOf(JSON.parse(strictJson(text)));
  } catch {
    return null;
  }
  if (parsed === null) return null;
  const entries: [string, string, unknown][] = [];
  for (const key of SWITCHES) {
    const raw = parsed[key];
    if (raw === undefined) continue;
    const table = objectOf(raw);
    if (table === null) {
      entries.push([key, '', raw]);
      continue;
    }
    for (const [name, value] of Object.entries(table)) {
      if (PLUGIN.test(name)) entries.push([key, name, value]);
    }
  }
  if (parsed[HOOKS_OFF] !== undefined) entries.push([HOOKS_OFF, '', parsed[HOOKS_OFF]]);
  return JSON.stringify(
    entries.toSorted((a, b) => `${a[0]}\0${a[1]}`.localeCompare(`${b[0]}\0${b[1]}`)),
  );
}

function switchText(text: string): string {
  return JSON.stringify((text.match(SWITCH_TEXT) ?? []).map((l) => l.trim()).toSorted());
}

// Whether replacing `before` (null when the file does not exist) with `after`
// changes how review-cycle is switched. Only the user makes that change.
export function touchesGate(before: string | null, after: string): boolean {
  const was = before === null ? '[]' : gateEntries(before);
  const now = gateEntries(after);
  if (was !== null && now !== null) return was !== now;
  // Claude Code ignores a file it cannot parse, so repairing or breaking one
  // that names a switch turns that switch on or off.
  const named = (before ?? '').match(SWITCH_TEXT) !== null || after.match(SWITCH_TEXT) !== null;
  if ((was === null) !== (now === null) && named) return true;
  // Neither side parses: compare the lines that name a switch.
  return switchText(before ?? '') !== switchText(after);
}

// The text an Edit call leaves, or null when `old` does not occur literally
// (the Edit tool also matches normalised quotes, which this does not attempt).
export function applyEdit(
  text: string,
  old: string,
  replacement: string,
  all: boolean,
): string | null {
  if (old === '' || !text.includes(old)) return null;
  return all ? text.replaceAll(old, replacement) : text.replace(old, () => replacement);
}

// `.claude` itself: a plugin's `.claude-plugin/` holds no settings.
const CLAUDE_DIR = /\.claude(?![-\w])|CLAUDE_CONFIG_DIR/i;
const WRITES =
  /(^|[^<&0-9])>|\b(rm|mv|cp|ln|tee|truncate|sponge|install|dd|rsync|python3?|node|bun|deno|tsx|ts-node|lua|osascript)\b|\b(sed|perl|ruby)\b[^|;&]*\s(-[a-zA-Z0-9]*i|--in-place)/;
// Removing a marketplace uninstalls the plugins installed from it.
const PLUGIN_CLI =
  /\bclaude\b[^|;&]*\bplugins?\s+(market(place)?\s+)?(disable|uninstall|remove|rm)\b/;

// Commands that write the files they are given.
const WRITERS = new Set([
  'rm',
  'mv',
  'cp',
  'ln',
  'tee',
  'truncate',
  'sponge',
  'install',
  'dd',
  'rsync',
]);
// Commands that edit a file in place when given `-i` or `--in-place`.
const IN_PLACE = new Set(['sed', 'perl', 'ruby']);
// Interpreters, whose writes are in code this reader does not follow.
const INTERPRETERS = /^(python[0-9.]*|node|bun|deno|tsx|ts-node|lua|osascript)$/;
// Shells, and commands that hand an argument to one, run a command line this
// reader does not parse.
const SHELLS = new Set([
  'bash',
  'sh',
  'zsh',
  'dash',
  'ksh',
  'fish',
  'su',
  'eval',
  'watch',
  'parallel',
  'flock',
  'script',
  'tmux',
  'screen',
]);
// `claude` as installed, or run through npx and the like as its package.
const CLAUDE = /^claude(-code)?(@[^/]*)?$/;
// Discarding output writes nothing anyone reads.
const writesFile = (w: Word): boolean => w.text !== '/dev/null';

const basename = (text: string): string =>
  text.slice(text.lastIndexOf('/') + 1).replace(/\.exe$/i, '');

// The text check's test, with what writes and what runs `claude plugin` read
// from the parsed command: quoted prose that mentions a writer, a redirect or
// a plugin subcommand, such as an issue description, is neither. Whether a
// settings file is named is still read from the whole text, so a path reached
// through `cd`, a variable or a loop counts.
export function bashTouchesGate(command: string): boolean {
  const parsed = parse(command);
  if ('error' in parsed) return textTouchesGate(command);
  const all = flatten(parsed.statements);
  if (all.some((st) => removesPlugin(st))) return true;
  if (all.some((st) => runsShell(st))) return textTouchesGate(command);
  const written = parsed.bareWrites.some(writesFile) || all.some((st) => writes(st));
  return written && namesSettings(command);
}

// So do `sudo -s` and `sudo -i` (clustered too, as `-iu`), `env -S`, and a
// prompt `claude -p` acts on.
function runsShell(st: Statement): boolean {
  const n = names(st);
  if (n.some((name) => SHELLS.has(name))) return true;
  const has = (flag: RegExp): boolean => st.words.some((w) => flag.test(w.text));
  if (n.includes('sudo') && has(/^(-[a-zA-Z]*[si][a-zA-Z]*|--shell|--login)$/)) return true;
  if (n.includes('env') && has(/^(-[a-zA-Z]*S|--split-string)/)) return true;
  return n.some((name) => CLAUDE.test(name)) && has(/^(-[a-zA-Z]*p|--print)$/);
}

// The text check, for a command line this reader cannot parse or a shell runs.
function textTouchesGate(text: string): boolean {
  if (PLUGIN_CLI.test(text)) return true;
  return WRITES.test(text) && namesSettings(text);
}

function namesSettings(text: string): boolean {
  return CLAUDE_DIR.test(text) && text.toLowerCase().includes('settings');
}

function flatten(list: Statement[]): Statement[] {
  return list.flatMap((st) => [st, ...st.inner.flatMap((inner) => flatten(inner))]);
}

function names(st: Statement): string[] {
  return st.words.map((w) => basename(w.text));
}

// `claude [options] plugin[s] [marketplace] disable|uninstall|remove|rm`.
function removesPlugin(st: Statement): boolean {
  const at = names(st).findIndex((n) => CLAUDE.test(n));
  if (at === -1) return false;
  const rest = st.words.slice(at + 1).map((w) => w.text);
  const plugin = rest.findIndex((w) => /^plugins?$/.test(w));
  if (plugin === -1) return false;
  const args = rest.slice(plugin + 1);
  const verb = /^market(place)?$/.test(args[0] ?? '') ? args[1] : args[0];
  return /^(disable|uninstall|remove|rm)$/.test(verb ?? '');
}

function writes(st: Statement): boolean {
  if (st.writes.some(writesFile)) return true;
  const n = names(st);
  if (n.some((name) => WRITERS.has(name) || INTERPRETERS.test(name))) return true;
  const inPlace = st.words.some((w) => /^(-[a-zA-Z0-9]*i|--in-place)/.test(w.text));
  return inPlace && n.some((name) => IN_PLACE.has(name));
}

files.hooks/shell.ts:
// Reads a Bash command into statements, as bash would. Pure: no `$`, no I/O.
//
// The user's shell aliases are expanded while reading, because bash replaces
// an alias's name with its text before it parses the command.

export type Word = {
  // The word's value with quotes removed; substitutions left as written.
  text: string;
  // True when the value depends on expansion ($VAR, $(…), backticks, ~).
  dynamic: boolean;
  // True when an unquoted glob or brace would make the shell rewrite it.
  pattern: boolean;
  // Set when an unquoted expansion may split it into several words.
  splits?: true;
};

export type Op = '&&' | '||' | '|' | ';' | '&' | '\n' | '';

type Heredoc = { body: string; quoted: boolean };

export type Statement = {
  words: Word[];
  // Command lists this statement runs besides itself: $(…), backticks, ( … ),
  // process substitutions, and substitutions inside ${…} and $((…)).
  inner: Statement[][];
  // Set when the statement is or contains a ( … ) group, a function body or an
  // array, rather than a simple command.
  group: boolean;
  heredocs: Heredoc[];
  // Set when the statement redirects to or from anything, a file or a descriptor.
  redirected: boolean;
  // The files the statement's output redirects write: `> f`, `>> f`, `&> f`.
  writes: Word[];
  op: Op;
  // Alias names among the words that were not expanded, because they stood
  // where this reader does not look for a command. The shell may still run
  // them: in a case arm, a function body, or as `eval`'s argument.
  aliases: string[];
};

// `text` is the command with its aliases expanded, as far as reading got.
export type Parsed =
  | { statements: Statement[]; text: string; bareWrites: Word[] }
  | { error: string; text: string };

// Shell aliases the Bash tool expands: name to replacement text.
export type ShellAliases = ReadonlyMap<string, string>;

// Reserved words after which bash reads a command, so an alias may follow.
const COMMAND_START = new Set([
  '!',
  '{',
  'if',
  'then',
  'else',
  'elif',
  'do',
  'while',
  'until',
  'time',
  'nocorrect',
  'noglob',
]);

// Bash stops at recursion, not depth; these bound a pathological table. The
// total is shared with the readers of substitutions, which nest.
const MAX_DEPTH = 50;
const MAX_EXPANSIONS = 10_000;

export const QUALIFIER = 'a zsh glob qualifier that runs code';

// What every reader of one command shares, nested readers included: the
// expansion budget, and the files written by a redirect that stands alone.
type Shared = { left: number; bareWrites: Word[] };

function newBudget(): Shared {
  return { left: MAX_EXPANSIONS, bareWrites: [] };
}

export function assignmentName(w: Word): string | null {
  const m = /^([A-Za-z_][A-Za-z0-9_]*)=/.exec(w.text);
  return m?.[1] ?? null;
}

export function statement(): Statement {
  return {
    words: [],
    inner: [],
    group: false,
    heredocs: [],
    redirected: false,
    writes: [],
    op: '',
    aliases: [],
  };
}

class Lexer {
  i = 0;
  // Open `case` statements, whose patterns end in a bare `)`.
  private cases = 0;
  private pending: { delim: string; stripTabs: boolean; quoted: boolean; st: Statement }[] = [];
  // Aliases being expanded, each until the end of its replacement text: bash
  // does not expand a name again inside its own expansion.
  private active: { name: string; end: number }[] = [];
  // Where the value of an alias ending in a blank ends: the word after it is
  // an alias candidate too. -1 when there is none.
  private aliasNextAt = -1;
  // Where the first word of an alias's value starts: bash tests it for an
  // alias wherever it stands. -1 when there is none.
  private firstAt = -1;
  // Each statement's last reserved word read as a command, such as `then` or
  // `time`; the same word as an argument (`echo time`) starts nothing.
  private reserved = new WeakMap<Statement, number>();

  constructor(
    public s: string,
    private readonly aliases: ShellAliases = new Map(),
    readonly budget: Shared = newBudget(),
  ) {}

  private ch(k = 0): string {
    return this.s[this.i + k] ?? '';
  }

  // Reads statements until end of input, or until an unmatched `)` when
  // parsing inside $( … ) or ( … ).
  list(inParen: boolean): Statement[] {
    // A case inside $( … ) ends its patterns with `)` too.
    const outerCases = this.cases;
    this.cases = 0;
    const out: Statement[] = [];
    let cur = statement();
    const end = (op: Op) => {
      cur.op = op;
      if (cur.words.length > 0 || cur.group || cur.inner.length > 0) out.push(cur);
      // `> file` alone truncates the file; it runs nothing, so it is no statement.
      else this.budget.bareWrites.push(...cur.writes);
      cur = statement();
    };
    while (this.i < this.s.length) {
      const before = this.i;
      const c = this.ch();
      if (c === ' ' || c === '\t' || c === '\r') {
        this.i++;
      } else if (c === '\\' && this.ch(1) === '\n') {
        this.i += 2;
      } else if (c === '\n') {
        this.i++;
        end('\n');
        this.heredocs();
      } else if (c === '#' && this.atWordStart()) {
        while (this.i < this.s.length && this.ch() !== '\n') this.i++;
      } else if (c === ')' && this.cases > 0) {
        // A `case` pattern's closing parenthesis; a command follows it.
        this.i++;
        this.firstAt = this.i;
      } else if (c === ')') {
        if (!inParen) throw new Error('unmatched )');
        this.i++;
        end('');
        this.cases = outerCases;
        return out;
      } else if (c === '(') {
        // A group at the start of a statement; later, a function definition's
        // `()` or a `[[ … =~ ( … ) ]]` pattern. Either way it may run code.
        this.i++;
        cur.inner.push(this.list(true));
        cur.group = true;
      } else if (c === ';' || c === '&' || c === '|') {
        const two = this.s.slice(this.i, this.i + 2);
        if (two === '&&' || two === '||') {
          this.i += 2;
          end(two);
        } else if (two === '&>') {
          this.redirect(cur);
        } else if (two === '|&') {
          this.i += 2;
          end('|');
        } else {
          this.i++;
          end(c);
        }
      } else if (c === '<' || c === '>') {
        this.redirect(cur);
      } else if (
        /[0-9]/.test(c) &&
        /^[0-9]+[<>]/.test(this.s.slice(this.i, this.i + 12)) &&
        this.atWordStart()
      ) {
        while (/[0-9]/.test(this.ch())) this.i++;
        this.redirect(cur);
      } else {
        const from = this.i;
        const next = this.aliasNextAt !== -1 && from >= this.aliasNextAt;
        if (next) this.aliasNextAt = -1;
        const first = this.firstAt !== -1 && from >= this.firstAt;
        if (first) this.firstAt = -1;
        const position = this.commandPosition(cur);
        const candidate = next || first || position;
        const w = this.word(cur);
        if (candidate && this.expandAlias(from)) continue;
        const name = this.aliasName(from);
        if (name !== null) cur.aliases.push(name);
        // Only as a command are these reserved words: `echo case` is not one.
        if (position && w.text === 'case' && !w.dynamic) this.cases++;
        if (position && w.text === 'esac' && !w.dynamic) this.cases = Math.max(0, this.cases - 1);
        // A function body's `{` follows `name()` or `function name`.
        const body = w.text === '{' && (cur.group || cur.words[0]?.text === 'function');
        if ((position || body) && !w.dynamic && COMMAND_START.has(w.text)) {
          this.reserved.set(cur, cur.words.length);
        }
        cur.words.push(w);
      }
      if (this.i === before)
        throw new Error(`cannot read the command at "${this.s.slice(this.i, this.i + 20)}"`);
    }
    if (inParen) throw new Error('unterminated (');
    if (this.pending.length > 0) throw new Error('unterminated heredoc');
    end('');
    this.cases = outerCases;
    return out;
  }

  // The alias named by the word read from `from`, as written: a quoted or
  // escaped name (`'gp'`, `\gp`) names none.
  private aliasName(from: number): string | null {
    const raw = this.s.slice(from, this.i).replaceAll('\\\n', '');
    return this.aliases.has(raw) ? raw : null;
  }

  // Whether the next word is read as a command: nothing but assignments since
  // the statement began or since a reserved word such as `{` or `then`.
  private commandPosition(cur: Statement): boolean {
    const start = this.reserved.get(cur) ?? -1;
    let rest = cur.words.slice(start + 1);
    // bash's `time -p` still reads a command next.
    if (cur.words[start]?.text === 'time' && rest[0]?.text === '-p' && !rest[0].dynamic) {
      rest = rest.slice(1);
    }
    return rest.every((w) => assignmentName(w) !== null);
  }

  // Replaces an alias name at `from` with its value, as bash does before
  // reading the command, and rewinds to read the value.
  private expandAlias(from: number): boolean {
    const raw = this.aliasName(from);
    const value = raw === null ? undefined : this.aliases.get(raw);
    if (raw === null || value === undefined) return false;
    this.active = this.active.filter((a) => a.end > from);
    if (this.active.some((a) => a.name === raw)) return false;
    if (this.active.length >= MAX_DEPTH || --this.budget.left < 0) {
      throw new Error('shell aliases nested too deep');
    }
    const shift = value.length - raw.length;
    for (const a of this.active) a.end += shift;
    if (this.aliasNextAt > from) this.aliasNextAt += shift;
    this.active.push({ name: raw, end: from + value.length });
    this.s = this.s.slice(0, from) + value + this.s.slice(this.i);
    this.i = from;
    if (/[ \t]$/.test(value)) this.aliasNextAt = from + value.length;
    // Bash tests the first word of a value for an alias wherever it stands.
    this.firstAt = from;
    return true;
  }

  private atWordStart(): boolean {
    const p = this.s[this.i - 1];
    return p === undefined || /[\s;&|()]/.test(p);
  }

  private redirect(cur: Statement): void {
    const rest = this.s.slice(this.i);
    const op = /^(<<<|<<-|<<|&>>|&>|>>|>&|<&|>\||<>|<|>)/.exec(rest)?.[0] ?? '>';
    this.i += op.length;
    cur.redirected = true;
    if ((op === '<' || op === '>') && this.ch() === '(') {
      // Process substitution: `<( … )` and `>( … )` run a command list.
      this.i++;
      cur.inner.push(this.list(true));
      return;
    }
    while (this.ch() === ' ' || this.ch() === '\t') this.i++;
    if (op === '<<' || op === '<<-') {
      const from = this.i;
      const target = this.word(cur);
      const quoted = /['"\\]/.test(this.s.slice(from, this.i));
      this.pending.push({ delim: target.text, stripTabs: op === '<<-', quoted, st: cur });
      return;
    }
    // `2>&1` and friends name a descriptor, not a file.
    if ((op === '>&' || op === '<&') && /^[0-9-]/.test(this.ch())) {
      while (/[0-9-]/.test(this.ch())) this.i++;
      return;
    }
    const target = this.word(cur);
    if (op.includes('>')) cur.writes.push(target);
  }

  // Heredoc bodies start on the line after their operator. An unquoted body
  // is expanded by the shell, so its substitutions run like any others.
  private heredocs(): void {
    for (const h of this.pending) {
      const lines: string[] = [];
      for (;;) {
        if (this.i >= this.s.length) throw new Error('unterminated heredoc');
        const nl = this.s.indexOf('\n', this.i);
        const line = this.s.slice(this.i, nl === -1 ? this.s.length : nl);
        this.i = nl === -1 ? this.s.length : nl + 1;
        if ((h.stripTabs ? line.replace(/^\t+/, '') : line) === h.delim) break;
        lines.push(line);
      }
      const body = lines.join('\n');
      h.st.heredocs.push({ body, quoted: h.quoted });
      if (!h.quoted && /\$\(|`/.test(body))
        h.st.inner.push(substitutionsIn(body, this.aliases, this.budget));
    }
    this.pending = [];
  }

  word(cur: Statement): Word {
    let text = '';
    let dynamic = false;
    let splits = false;
    let pattern = false;
    let bracket = false;
    let brace = false;
    const start = this.i;
    while (this.i < this.s.length) {
      const c = this.ch();
      if (c === '(' && text.endsWith('=')) {
        // An array assignment, `name=( … )`: its elements may substitute.
        this.i++;
        cur.inner.push(this.list(true));
        cur.group = true;
        dynamic = true;
        continue;
      }
      // A `(` inside a word is a zsh group or a ksh/bash extglob (`g(i)t`,
      // `@(git)`), so it stays in the word as a pattern. `name()` defines a
      // function; a statement's leading `(` never reaches here.
      if (c === '(' && this.ch(1) !== ')') {
        const end = this.closing(this.i, '(', ')');
        const body = this.s.slice(this.i + 1, end - 1);
        // A group with no unquoted `|` can be zsh glob qualifiers, whose `e`
        // and `+name` run code. Where it sits is not checked: quote removal
        // and brace expansion can still leave it last in a word.
        const bare = body.replaceAll(/'[^']*'|"(?:\\.|[^"\\])*"|\\./g, '');
        if (!bare.includes('|') && /e|\+[A-Za-z_]/.test(body)) throw new Error(QUALIFIER);
        // The shell still runs a substitution inside the group: `x($(cmd))`.
        if (/[$`<>]/.test(body)) {
          cur.inner.push(new Lexer(body, this.aliases, this.budget).list(false));
          dynamic = true;
        }
        text += this.s.slice(this.i, end);
        this.i = end;
        pattern = true;
        continue;
      }
      if (/[\s;&|<>()]/.test(c)) break;
      if (c === '\\') {
        if (this.ch(1) === '\n') {
          this.i += 2;
          continue;
        }
        text += this.ch(1);
        this.i += 2;
      } else if (c === "'") {
        const close = this.s.indexOf("'", this.i + 1);
        if (close === -1) throw new Error("unterminated '");
        text += this.s.slice(this.i + 1, close);
        this.i = close + 1;
      } else if (c === '$' && this.ch(1) === "'") {
        const close = this.ansiEnd(this.i + 2);
        text += decodeAnsiC(this.s.slice(this.i + 2, close));
        this.i = close + 1;
      } else if (c === '"') {
        this.i++;
        for (;;) {
          if (this.i >= this.s.length) throw new Error('unterminated "');
          const d = this.ch();
          if (d === '"') {
            this.i++;
            break;
          }
          if (d === '\\' && /["\\$`\n]/.test(this.ch(1))) {
            if (this.ch(1) !== '\n') text += this.ch(1);
            this.i += 2;
          } else if (d === '$' || d === '`') {
            const expanded = this.expansion(cur);
            text += expanded;
            dynamic = true;
            // These give several words even in double quotes: "$@", "${a[@]}",
            // "${u:-$@}", bash's "${!p@}", zsh's "${(@)a}", "${=x}", "${(s: :)x}"
            // and "${(Z+c+)x}" (measured in bash and zsh).
            const zshIndex = /^\$\w+$/.test(expanded) && this.s.startsWith('[@]', this.i);
            const several =
              /^\$(@|\{[#!]?@|\{[^}]*\[@\]|\{=|\{\([^)]*[@sfzZ0]|\{![^}]*@\}|\{[^}]*\$\{?@)/;
            if (zshIndex || several.test(expanded)) {
              splits = true;
            }
          } else {
            text += d;
            this.i++;
          }
        }
      } else if (c === '$' || c === '`') {
        text += this.expansion(cur);
        dynamic = true;
        splits = true;
      } else {
        if (c === '~' && this.i === start) dynamic = true;
        // `[` and `{` start a pattern only once an unquoted `]` or `}` closes
        // it, so `[`, the test command, stays a plain word. zsh's extended
        // globs (`#`, `^`, `~` inside a word) need no closer.
        if (c === '*' || c === '?' || c === '#' || c === '^' || (c === '~' && this.i !== start))
          pattern = true;
        else if (c === '[') bracket = true;
        else if (c === '{') brace = true;
        else if ((c === ']' && bracket) || (c === '}' && brace)) pattern = true;
        text += c;
        this.i++;
      }
    }
    return splits ? { text, dynamic, pattern, splits } : { text, dynamic, pattern };
  }

  private ansiEnd(from: number): number {
    for (let j = from; j < this.s.length; j++) {
      if (this.s[j] === '\\') j++;
      else if (this.s[j] === "'") return j;
    }
    throw new Error("unterminated $'");
  }

  // The index past the bracket closing the one at `open`.
  private closing(open: number, left: string, right: string): number {
    let depth = 0;
    for (let j = open; j < this.s.length; j++) {
      const c = this.s[j];
      if (c === '\\') j++;
      else if (c === "'" || c === '"') {
        // A quoted bracket does not count: `${x:-"}"}`.
        const close = this.s.indexOf(c, j + 1);
        if (close === -1) break;
        j = close;
      } else if (c === left) depth++;
      else if (c === right && --depth === 0) return j + 1;
    }
    throw new Error(`unterminated ${left}`);
  }

  // Reads one `$…` or backtick expansion starting at this.i, recording any
  // command list it runs, and returns its source text.
  private expansion(cur: Statement): string {
    const from = this.i;
    const c = this.ch();
    if (c === '`') {
      const close = this.s.indexOf('`', this.i + 1);
      if (close === -1) throw new Error('unterminated `');
      const body = this.s.slice(this.i + 1, close).replaceAll('\\`', '`');
      cur.inner.push(new Lexer(body, this.aliases, this.budget).list(false));
      this.i = close + 1;
    } else if (this.ch(1) === '(' && this.ch(2) === '(') {
      const close = this.closing(this.i + 1, '(', ')');
      cur.inner.push(
        substitutionsIn(this.s.slice(this.i + 3, close - 2), this.aliases, this.budget),
      );
      this.i = close;
    } else if (this.ch(1) === '(') {
      this.i += 2;
      cur.inner.push(this.list(true));
    } else if (this.ch(1) === '{') {
      const close = this.closing(this.i + 1, '{', '}');
      cur.inner.push(
        substitutionsIn(this.s.slice(this.i + 2, close - 1), this.aliases, this.budget),
      );
      this.i = close;
    } else {
      this.i++;
      while (/[A-Za-z0-9_@*#?$!-]/.test(this.ch())) {
        this.i++;
        if (!/[A-Za-z0-9_]/.test(this.ch(-1))) break;
      }
    }
    return this.s.slice(from, this.i);
  }
}

const ANSI_C: Record<string, string> = {
  a: '\u0007',
  b: '\b',
  e: '\u001B',
  E: '\u001B',
  f: '\f',
  n: '\n',
  r: '\r',
  t: '\t',
  v: '\v',
};

// zsh lists a control byte in an alias value as `\C-M`, DEL as `\C-?`, and a
// byte with the high bit as `\M-` before either form; bash never writes these.
// The listing does not escape the byte after `\C-` or `\M-`.
const LISTING_ESCAPE =
  /\\(M-\\C-.|M-\\[tn]|M-.|C-.|x[0-9a-fA-F]{1,2}|u[0-9a-fA-F]{1,4}|U[0-9a-fA-F]{1,8}|[0-7]{1,3}|.)/g;
const COMMAND_ESCAPE =
  /\\(C-?|M-?|x[0-9a-fA-F]{0,2}|u[0-9a-fA-F]{0,4}|U[0-9a-fA-F]{0,8}|[0-7]{1,3}|[\s\S])|[\s\S]/gu;

function zshControl(code: number): number {
  return code === 63 ? 127 : code & 0x9f;
}

// One escape after its backslash. zsh drops the backslash of an escape it does
// not know, `\c` included: `$'c\ommit'` and `$'\commit'` run as `commit`.
function escapeValue(esc: string): string {
  const kind = esc[0] ?? '';
  if (kind === 'x' || kind === 'u' || kind === 'U') {
    return String.fromCodePoint(Number.parseInt(esc.slice(1), 16) || 0);
  }
  if (/[0-7]/.test(kind)) return String.fromCodePoint(Number.parseInt(esc, 8));
  return ANSI_C[kind] ?? kind;
}

// The value zsh gives a command's `$'…'` word, which the Bash tool runs:
// `$'co\x6dmit'` is `commit`. `\C` and `\M`, a `-` after either optional, set
// control and meta on the next character, escaped or not, except a `\u` or
// `\U` one; with no next character they add nothing, so `co$'\C'mmit` is
// `commit`. As zsh does, meta set after control applies first.
function decodeAnsiC(body: string): string {
  let out = '';
  let control = false;
  let meta: 'before' | 'after' | undefined;
  for (const [whole, esc] of body.matchAll(COMMAND_ESCAPE)) {
    if (esc?.[0] === 'C' && esc.length <= 2) control = true;
    else if (esc?.[0] === 'M' && esc.length <= 2) meta = control ? 'before' : 'after';
    else if (esc?.[0] === 'u' || esc?.[0] === 'U') out += escapeValue(esc);
    else {
      let code = (esc === undefined ? whole : escapeValue(esc)).codePointAt(0) ?? 0;
      if (meta === 'before') code |= 0x80;
      if (control) code = zshControl(code);
      if (meta === 'after') code |= 0x80;
      control = false;
      meta = undefined;
      out += String.fromCodePoint(code);
    }
  }
  return out;
}

// An alias value as zsh's `alias` listing writes it.
function decodeListing(body: string): string {
  return body.replaceAll(LISTING_ESCAPE, (_, esc: string) => {
    const control = (at: number): number => zshControl(esc.codePointAt(at) ?? 0);
    if (esc.startsWith(String.raw`M-\C-`)) return String.fromCodePoint(0x80 | control(5));
    // zsh lists 0x89 and 0x8a as `\M-\t` and `\M-\n`, reading them back so.
    if (/^M-\\[tn]$/.test(esc)) return String.fromCodePoint(0x80 | (esc[3] === 't' ? 9 : 10));
    if (esc.startsWith('M-')) return String.fromCodePoint(0x80 | (esc.codePointAt(2) ?? 0));
    if (esc.startsWith('C-')) return String.fromCodePoint(control(2));
    return escapeValue(esc);
  });
}

// The command lists substituted into text that is not itself a command: the
// body of `${…}`, `$((…))` or an unquoted heredoc.
function substitutionsIn(text: string, aliases: ShellAliases, budget?: Shared): Statement[] {
  const found: Statement[] = [];
  for (let j = 0; j < text.length; j++) {
    const at = text[j];
    if (at === '\\') {
      j++;
    } else if (at === '`' || (at === '$' && (text[j + 1] === '(' || text[j + 1] === '{'))) {
      const lexer = new Lexer(text.slice(j), aliases, budget);
      const holder = statement();
      // word() reads the expansion exactly as it is read anywhere else.
      holder.words.push(lexer.word(holder));
      if (holder.inner.length > 0) found.push(holder);
      j += Math.max(lexer.i - 1, 0);
    }
  }
  return found;
}

export function parse(command: string, aliases: ShellAliases = new Map()): Parsed {
  const lexer = new Lexer(command, aliases);
  try {
    const statements = lexer.list(false);
    return { statements, text: lexer.s, bareWrites: lexer.budget.bareWrites };
  } catch (error) {
    return { error: error instanceof Error ? error.message : String(error), text: lexer.s };
  }
}

// As Claude Code picks the shell for its own snapshot: by name.
function shellKind(path: string): 'zsh' | 'bash' | null {
  if (path.includes('zsh')) return 'zsh';
  return path.includes('bash') ? 'bash' : null;
}

// Login files can print to stdout, so the aliases sit between two marker
// lines; an rc that `exec`s away never prints the second. `tag` is fresh per
// read, so no rc file or alias value prints a marker line by accident.
function markers(tag: string): [string, string] {
  return [`review-cycle: aliases ${tag}`, `review-cycle: end of aliases ${tag}`];
}

// Claude Code's own listing, so the gate holds the Bash tool's exact values.
const LISTING = "alias | sed 's/^alias //g' | sed 's/^/alias -- /' | head -n 1000";

// Laid out as Claude Code's snapshot script is: bash reads a line whole before
// running it, so an alias the rc defines applies only from the next line. The
// rc path is a literal and its existence decided by the caller, as Claude Code
// does, so an rc that moves $HOME or redefines `[` changes nothing here; with no
// rc there is nothing to list. An rc's DEBUG trap would print between the
// markers, and its own `echo` function would print the markers.
export function aliasScript(rc: string | null, tag: string): string {
  const [start, end] = markers(tag);
  const file = rc === null ? null : `'${rc.replaceAll("'", String.raw`'\''`)}'`;
  const lines = [`trap - DEBUG 2>/dev/null; builtin echo; builtin echo '${start}'`];
  if (file !== null) lines.unshift(`source ${file} < /dev/null > /dev/null 2>&1`);
  if (file !== null) lines.push(LISTING);
  lines.push(`builtin echo '${end}'`);
  return lines.join('\n');
}

// The aliases a reader's output holds, or null when the shell stopped short.
// Every listing line starts `alias -- `; anything else between the markers is
// the rc's own output, such as an ERR trap's.
export function readAliases(out: string, tag: string): Map<string, string> | null {
  const [startLine, endLine] = markers(tag);
  const lines = out.split('\n');
  const start = lines.indexOf(startLine);
  const end = lines.lastIndexOf(endLine);
  if (start === -1 || end <= start) return null;
  return parseShellAliases(lines.slice(start + 1, end).join('\n'), true);
}

// The shell and rc file Claude Code uses for its own snapshot.
export function aliasShell(
  claudeShell: string | undefined,
  shell: string | undefined,
): { path: string; rc: '.zshrc' | '.bashrc' } {
  const usable = (s: string | undefined) => (s !== undefined && shellKind(s) ? s : undefined);
  const path = usable(claudeShell) ?? usable(shell) ?? 'zsh';
  return { path, rc: shellKind(path) === 'bash' ? '.bashrc' : '.zshrc' };
}

// The close of a `$'…'` in an alias listing. zsh does not escape the byte after
// `\C-` or `\M-`, so `$'a\C-\'` and `$'x\M-'y'` end at their last quote.
function ansiEnd(s: string, from: number): number {
  for (let j = from; j < s.length; j++) {
    if (s[j] === '\\') {
      if (s.startsWith(String.raw`\M-\C-`, j)) j += 6;
      else if (s.startsWith(String.raw`\M-`, j) || s.startsWith(String.raw`\C-`, j)) j += 3;
      else j++;
    } else if (s[j] === "'") return j;
  }
  return s.length;
}

// A login file can print a terminal escape sequence ahead of a line. Control
// characters inside a value stay: bash reads `\x01#` as a word, not a comment.
function printable(line: string): string {
  const bell = line.startsWith('\u001B]') ? line.indexOf('\u0007') : -1;
  return line.slice(bell + 1);
}

// Whether `s` ends inside a '…' or $'…' quote.
function quoteOpen(s: string): boolean {
  let i = 0;
  while (i < s.length) {
    if (s.startsWith("$'", i)) {
      const end = ansiEnd(s, i + 2);
      if (end >= s.length) return true;
      i = end + 1;
    } else if (s[i] === "'") {
      const end = s.indexOf("'", i + 1);
      if (end === -1) return true;
      i = end + 1;
    } else {
      i += s[i] === '\\' ? 2 : 1;
    }
  }
  return false;
}

// A value as the shell quoted it: '…', $'…' and backslash escapes,
// concatenated. zsh ends a value holding a quote with `'\'`, bash with `'\'''`.
function unquoteWord(s: string): string {
  let out = '';
  let i = 0;
  while (i < s.length) {
    if (s.startsWith("$'", i)) {
      const end = ansiEnd(s, i + 2);
      out += decodeListing(s.slice(i + 2, end));
      i = end + 1;
    } else if (s[i] === "'") {
      const end = s.indexOf("'", i + 1);
      if (end === -1) return out + s.slice(i + 1);
      out += s.slice(i + 1, end);
      i = end + 1;
    } else if (s[i] === '\\' && i + 1 < s.length) {
      out += s[i + 1];
      i += 2;
    } else {
      out += s[i];
      i++;
    }
  }
  return out;
}

// Alias definitions as `alias` prints them in zsh (`name=value`) or bash
// (`alias name='value'`), or as a Claude Code shell snapshot holds them
// (`alias -- name='value'`, among function bodies that are skipped).
export function parseShellAliases(out: string, listing = false): Map<string, string> {
  const aliases = new Map<string, string>();
  const lines = out.split('\n').map((l) => printable(l));
  const prefixed = listing || lines.some((l) => l.startsWith('alias '));
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i] ?? '';
    if (prefixed && !raw.startsWith('alias ')) continue;
    const m = /^('[^']*'|[^=\s]+)=(.*)$/s.exec(raw.replace(/^alias\s+(--\s+)?/, ''));
    if (!m?.[1]) continue;
    let value = m[2] ?? '';
    // bash prints a value holding a newline across lines, quote still open.
    while (quoteOpen(value) && i + 1 < lines.length) value += `\n${lines[++i] ?? ''}`;
    aliases.set(m[1].replaceAll("'", ''), unquoteWord(value));
  }
  return aliases;
}

files.hooks/slop.ts:
// Pure. Narration that dodges the line patterns cannot dodge arithmetic, so
// the text the tool wrote is also checked for comment density. Borderline
// cases are left to the cleanup agent.

export type Written = {
  path: string;
  // The file's text after the tool ran.
  file: string;
  // What the tool wrote: a Write's content or an Edit's new_string.
  text: string;
  // An Edit's old_string; null for a Write, whose text is the whole file and
  // may open with a header. An Edit that creates a file is judged as an edit.
  replaced: string | null;
};

const BINARY = /\.(lock|lockb|png|jpe?g|gif|webp|pdf|zip|tar|gz|bin|exe|so|dylib|dll|wasm)$/i;
const GENERATED = /\/(node_modules|\.git|dist|build|target|\.next|\.venv)\//;
// '#' is a heading in prose, and prose cleanup is the de-slopify skill's job.
const PROSE = /\.(md|markdown|txt|rst|adoc)$/i;
// '#' documents these formats; a comment-heavy config is not slop.
const CONFIG = /\.(ya?ml|toml|ini|cfg|conf)$/i;
// Larger files are not scanned: they are generated or data, and slow to read.
export const MAX_BYTES = 1_048_576;

// The star, '#' and '--' forms need whitespace or the line's end after them,
// so C dereferences (*p = 1;), #include, #[attributes], shebangs and --i do
// not count as comments.
const COMMENT = /^\s*(\/\/|#(\s|$)|--(\s|\[|$)|\/\*|\*(\s|\/|$))/;

const PATTERNS: readonly { label: string; line: RegExp; unless?: RegExp }[] = [
  {
    label: 'Section-marker comments (per policy: avoid)',
    line: /^\s*(\/\/|#|--|\/\*)\s*={3,}/,
  },
  {
    label: 'Likely restate-the-code comments',
    line: /^\s*(\/\/|#|--)\s+(initializes|fetches|creates|validates|downloads|sets|gets|returns|handles|processes|increments|decrements|iterates over)\s+/,
  },
  {
    label: 'AI-flavored comment phrasings',
    line: /^\s*(\/\/|#|--)\s+(Here we|Let's|Let us|We can|This (function|method|class|component|module)( does| handles| simply| basically))/,
  },
  {
    label: 'Hedge-prefix comments (consider rewording or removing)',
    line: /^\s*(\/\/|#|--)\s+(Note|Important|NB|FYI):/,
  },
  {
    label: 'TODO/FIXME without ticket reference',
    line: /^\s*(\/\/|#|--)\s+(TODO|FIXME|HACK|XXX)(\s*:|\s+[^#A-Z0-9h])/,
    unless: /#[0-9]+|[A-Z]{2,}-[0-9]+|https?:\/\//,
  },
  {
    label: "Hedge words in comments (per policy: avoid 'obviously', 'basically', 'just')",
    line: /^\s*(\/\/|#|--)\s.*(obviously|basically|essentially|simply|just |actually )/,
  },
  {
    label:
      'History-flavored comments (describe the current invariant; the before/after story belongs in the commit message)',
    line: /^\s*(\/\/|#|--)\s.*(previously|formerly|used to be |no longer |renamed from |as it did (while|when|before)|after (the|this) (refactor|review|migration|change))/i,
  },
];

export function skipsPath(path: string): boolean {
  return BINARY.test(path) || GENERATED.test(path) || PROSE.test(path);
}

function lines(text: string): string[] {
  return text.replace(/\n+$/, '').split('\n');
}

// A Write is the whole file, whose header comment is legitimate: drop the
// shebang and the leading run of comment and blank lines before counting.
function withoutHeader(text: string): string[] {
  const all = lines(text);
  const body = all.findIndex(
    (l, i) => !(i === 0 && /^\s*#!/.test(l)) && !COMMENT.test(l) && /\S/.test(l),
  );
  return body === -1 ? [] : all.slice(body);
}

function density(w: Written): string | null {
  const written = w.replaced === null ? withoutHeader(w.text) : lines(w.text);
  if (written.join('\n') === '') return null;
  const total = written.filter((l) => l.length > 0).length;
  const comments = written.filter((l) => COMMENT.test(l)).length;
  const nonblank = written.filter((l) => /\S/.test(l)).length;
  // Rewriting a comment block as a comment block is comment-editing, often
  // fixing this check's own finding; both sides must be all comment, so a
  // one-line comment anchor cannot wave a narrated block through.
  const old = w.replaced === null ? [] : lines(w.replaced).filter((l) => /\S/.test(l));
  const oldComments = old.filter((l) => COMMENT.test(l)).length;
  if (old.length > 0 && oldComments >= old.length && nonblank > 0 && comments >= nonblank) {
    return null;
  }
  if (comments < 4 || total === 0 || Math.floor((comments * 100) / total) < 30) return null;
  return `${comments} of ${total} written lines are comments. Per the comment policy most WHAT-comments must be removed; keep only those stating a non-obvious WHY.`;
}

// Each finding as its label and up to three `line:text` matches.
export function slopFindings(w: Written): string[] {
  if (skipsPath(w.path)) return [];
  const findings: string[] = [];
  if (!CONFIG.test(w.path)) {
    const dense = density(w);
    if (dense) findings.push(`High comment density in this edit:\n${dense}`);
  }
  const file = lines(w.file);
  for (const p of PATTERNS) {
    const hits = file
      .map((l, i) => `${i + 1}:${l}`)
      .filter((_, i) => p.line.test(file[i] ?? '') && !p.unless?.test(file[i] ?? ''))
      .slice(0, 3);
    if (hits.length > 0) findings.push(`${p.label}:\n${hits.join('\n')}`);
  }
  return findings;
}

export function slopDirective(path: string, findings: string[]): string {
  return `review-cycle: comment slop detected in ${path}. Fix it NOW with a follow-up Edit, before continuing with the task — the comment policy is mandatory, not advisory. Remove every comment that restates WHAT the code does; keep a comment only when it states a non-obvious WHY the code cannot express, and compress kept comments to one or two lines — consequences the reader can derive, backstory, and before/after history go in the commit message, not the code. Do not wait to be asked.\n\n${findings.join('\n\n')}`;
}

files.hooks/sweep.ts:
// Ends what a review cycle's legs left running in its scratch directory, then
// removes it. Takes its process runner and clock as parameters, so it holds no
// `$` and runs against real processes in tests.

export type Run = (argv: string[]) => Promise<{ exitCode: number; stdout: string; stderr: string }>;
export type Sleep = (ms: number) => Promise<void>;

export type Swept = { dir: string; stopped: number; removed: boolean; errors: string[] };

// Time a TERM, then a KILL, gets before the next look.
const GRACE_MS = 500;

// The path followed by anything that cannot continue a file name, so a quoted
// or `;`-ended mention matches and `<dir>.log` or `<dir>-old` does not.
function patternOf(dir: string): string {
  const escaped = dir.replaceAll(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`);
  return `${escaped}([^-.A-Za-z0-9_]|$)`;
}

function pidsIn(stdout: string, own: number): Set<number> {
  const pids = new Set<number>();
  for (const line of stdout.split('\n')) {
    const pid = Number(line.trim());
    if (Number.isInteger(pid) && pid > 1 && pid !== own) pids.add(pid);
  }
  return pids;
}

// pgrep as well as lsof: a reader blocked opening a pipe under `dir` holds no
// file yet, so lsof misses it. Exit 1 is "no match" for both; a death by
// signal also reads as 1 through the runner, which no look here can tell apart.
async function holders(run: Run, dir: string, own: number, errors: string[]): Promise<Set<number>> {
  const pids = new Set<number>();
  const lsof = await run(['lsof', '-t', '+D', dir]);
  if (lsof.exitCode > 1)
    errors.push(`lsof failed: ${lsof.stderr.trim() || `exit ${lsof.exitCode}`}`);
  for (const pid of pidsIn(lsof.stdout, own)) pids.add(pid);
  const pgrep = await run(['pgrep', '-f', patternOf(dir)]);
  if (pgrep.exitCode > 1)
    errors.push(`pgrep failed: ${pgrep.stderr.trim() || `exit ${pgrep.exitCode}`}`);
  for (const pid of pidsIn(pgrep.stdout, own)) pids.add(pid);
  return pids;
}

function listed(pids: Set<number>): string[] {
  return [...pids].map(String);
}

export async function sweep(run: Run, sleep: Sleep, dir: string, own: number): Promise<Swept> {
  const errors: string[] = [];
  const found = await holders(run, dir, own, errors);
  let left = new Set<number>();
  if (found.size > 0) {
    // kill's exit status is not read: a process that exited between the look
    // and the signal fails it too. The next look decides.
    await run(['kill', '-TERM', ...listed(found)]);
    await sleep(GRACE_MS);
    left = await holders(run, dir, own, errors);
    if (left.size > 0) {
      await run(['kill', '-KILL', ...listed(left)]);
      await sleep(GRACE_MS);
      left = await holders(run, dir, own, errors);
    }
    if (left.size > 0) errors.push(`still running after KILL: ${listed(left).join(' ')}`);
  }
  const rm = await run(['rm', '-rf', '--', dir]);
  const removed = rm.exitCode === 0;
  if (!removed) errors.push(`rm failed: ${rm.stderr.trim() || `exit ${rm.exitCode}`}`);
  const stopped = [...found].filter((pid) => !left.has(pid)).length;
  return { dir, stopped, removed, errors };
}

files.hooks/witness.ts:
// What counts as a review, and which paths of a commit one covers. Pure.
//
// A review is a review-cycle leg that delivered its receipt. It covers a path
// only where the working tree held the same content when the leg was spawned
// and when its turn completed: an edit made while it ran, by the leg itself or
// anyone else, is content it may never have read. A committed path is covered
// when some review covers exactly the content being committed there. Anything
// edited after the last reviewer saw it is unreviewed until a reviewer sees it
// again: inline fixes included.

export const EMPTY_TREE = '4b825dc642cb6eb9a060e54bf8d69288fbee4904';

// State and editor preferences, not reviewable code: changes here never need a
// review, and never count against a commit.
export const EXCLUDES = [
  ':(exclude,glob).beads/**',
  ':(exclude,glob)**/.beads/**',
  ':(exclude,glob).trekker/**',
  ':(exclude,glob)**/.trekker/**',
  ':(exclude,glob).vscode/**',
  ':(exclude,glob)**/.vscode/**',
  ':(exclude,glob).idea/**',
  ':(exclude,glob)**/.idea/**',
  ':(exclude,glob).zed/**',
  ':(exclude,glob)**/.zed/**',
  ':(exclude,glob).cursor/**',
  ':(exclude,glob)**/.cursor/**',
  ':(exclude,glob).fleet/**',
  ':(exclude,glob)**/.fleet/**',
];

// The config is always reviewable: an unreviewed `ignore` entry could hide the
// very change it was added alongside.
export const CONFIG_PATH = '.claude/review-cycle.json';

export function ignoresOf(configText: string | null): string[] {
  if (!configText) return [];
  try {
    const cfg = JSON.parse(configText) as { ignore?: unknown };
    if (!Array.isArray(cfg.ignore)) return [];
    return cfg.ignore
      .filter((p): p is string => typeof p === 'string' && p.length > 0)
      .map((p) => `:(exclude,glob)${p}`);
  } catch {
    return [];
  }
}

// cleanup edits the tree it is given; it is never a reviewer.
export function isReviewerType(type?: string): boolean {
  return (
    typeof type === 'string' && type.startsWith('review-cycle:') && type !== 'review-cycle:cleanup'
  );
}

// The two receipt lines, together, near the top of the report: a heading or a
// sentence may come first, a receipt buried in the body does not count.
export function hasReceipt(answer: string): boolean {
  const lines = answer
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean)
    .slice(0, 6);
  return lines.some(
    (l, i) =>
      l.startsWith('execution:') && (lines[i + 1] ?? '').startsWith('attempted-but-failed:'),
  );
}

export type Review = {
  type: string;
  // The working tree at spawn and at completion; both must match a path.
  trees: readonly [spawn: string, completed: string];
  // Paths the reviewed tree changed against HEAD at the time: what the
  // reviewer was shown. A review covers only these.
  reviewedPaths: readonly string[];
};

export type PathState = 'covered' | 'edited-after-review' | 'never-reviewed';
export type Row = { path: string; state: PathState };

// `differing` maps each reviewed tree to the committed paths where it and the
// tree being committed disagree.
export function coverage(
  changed: readonly string[],
  reviews: readonly Review[],
  differing: ReadonlyMap<string, ReadonlySet<string>>,
): Row[] {
  return changed.map((path) => {
    const agrees = (tree: string) => !(differing.get(tree)?.has(path) ?? true);
    // The reviewer must have been shown the path, not merely held it unchanged.
    if (reviews.some((r) => r.reviewedPaths.includes(path) && r.trees.every(agrees))) {
      return { path, state: 'covered' };
    }
    return {
      path,
      state: reviews.some((r) => r.reviewedPaths.includes(path))
        ? 'edited-after-review'
        : 'never-reviewed',
    };
  });
}

export function uncoveredOf(rows: readonly Row[]): Row[] {
  return rows.filter((r) => r.state !== 'covered');
}

export function describeUncovered(rows: readonly Row[]): string {
  const edited = rows.filter((r) => r.state === 'edited-after-review').map((r) => r.path);
  const never = rows.filter((r) => r.state === 'never-reviewed').map((r) => r.path);
  const parts: string[] = [];
  if (edited.length > 0) parts.push(`edited after the last review: ${edited.join(', ')}`);
  if (never.length > 0) parts.push(`never reviewed: ${never.join(', ')}`);
  return parts.join('; ');
}

files.hooks/publish.ts:
// Package publishes, the release step's commands besides `gh release`. Pure:
// no `$`, no I/O. A package script (`pnpm release`, `npm run publish`) runs
// whatever it holds, so it is not read.

import type { GhAction } from './github';
import type { Word } from './shell';

// Options that take a value before the command, from each tool's `--help`
// (npm 11.17, pnpm 12.7, cargo 1.98, bun 1.4); `publish`'s own value options
// are included, since npm and pnpm accept them first (`npm --tag beta publish`).
const PUBLISH_VALUES = ['--tag', '--access', '--otp', '--registry', '--loglevel'];
type Publisher = {
  values: ReadonlySet<string>;
  publishes: 'publish' | 'release';
  // The shortest abbreviation the tool accepts: npm takes any from `pu`
  // (npm 11.17: `npm pu --help` prints "Publish a package"; `npm p` is unknown).
  abbreviates?: string;
  // Words that pass the command on: `pnpm recursive publish`.
  passes?: ReadonlySet<string>;
  // Whether `--dry-run` is known to skip the upload.
  dryRuns: boolean;
};
const PUBLISHERS: Record<string, Publisher> = {
  npm: {
    values: new Set([
      '-w',
      '--workspace',
      '--prefix',
      '--userconfig',
      '--cache',
      ...PUBLISH_VALUES,
    ]),
    publishes: 'publish',
    abbreviates: 'pu',
    dryRuns: true,
  },
  pnpm: {
    values: new Set([
      '-C',
      '--dir',
      '-F',
      '--filter',
      '--filter-prod',
      '--reporter',
      '--loglevel',
      '--workspace-concurrency',
      ...PUBLISH_VALUES,
    ]),
    publishes: 'publish',
    passes: new Set(['recursive', 'm', 'multi']),
    dryRuns: true,
  },
  yarn: { values: new Set(['--cwd']), publishes: 'publish', dryRuns: false },
  bun: { values: new Set(['--cwd']), publishes: 'publish', dryRuns: true },
  cargo: {
    values: new Set(['-Z', '--config', '-C', '--color']),
    publishes: 'publish',
    dryRuns: true,
  },
  // `oakum release` has no dry run.
  oakum: { values: new Set(), publishes: 'release', dryRuns: false },
};

function publishes(publisher: Publisher, word: string): boolean {
  const { abbreviates } = publisher;
  if (abbreviates) return word.startsWith(abbreviates) && publisher.publishes.startsWith(word);
  return word === publisher.publishes;
}

// A publish read as text, for a command that does not parse: a publisher, then
// its command written in full later on the same line.
const toolsByCommand = new Map<string, string[]>();
for (const [tool, { publishes }] of Object.entries(PUBLISHERS)) {
  toolsByCommand.set(publishes, [...(toolsByCommand.get(publishes) ?? []), tool]);
}
export const PUBLISH_TEXT = new RegExp(
  [...toolsByCommand]
    .map(([command, tools]) => String.raw`\b(${tools.join('|')})\b[^|;&\n]*\b${command}\b`)
    .join('|'),
);

// The package managers whose `run` hands the rest of the words to a script.
const RUNS_SCRIPTS = new Set(['npm', 'pnpm', 'yarn', 'bun']);

// Whether the words ask for a dry run, the last word deciding: `--dry-run`,
// `--dry-run=true`, and cargo's `-n` alone or in a cluster (`-qn`).
function dryRun(name: string, words: string[]): boolean {
  let dry = false;
  for (const [i, t] of words.entries()) {
    const value = /^--dry-run=(.*)$/.exec(t)?.[1];
    if (value !== undefined) dry = !/^(false|0)$/.test(value);
    else if (t === '--dry-run') dry = !/^(false|0)$/.test(words[i + 1] ?? '');
    else if (t === '--no-dry-run') dry = false;
    else if (name === 'cargo' && /^-[a-zA-Z]+$/.test(t)) dry ||= cargoCluster(t);
  }
  return dry;
}

// Whether a cluster of cargo's short options holds `-n` before a letter that
// takes the rest of the cluster as its value (`-pn` names package `n`).
function cargoCluster(cluster: string): boolean {
  for (const letter of cluster.slice(1)) {
    if (letter === 'n') return true;
    if ('pjFZC'.includes(letter)) return false;
  }
  return false;
}

const basename = (p: string): string => p.slice(p.lastIndexOf('/') + 1);

// The publish each word starts, by its index: a publisher at any word runs
// (`timeout 60 npm publish`, `npx oakum release`). The words after `npm run`
// are a script's name and arguments, so the scan stops there.
export function publishActionsOf(words: Word[]): ReadonlyMap<number, GhAction> {
  const found = new Map<number, GhAction>();
  // A Yarn command running npm (`yarn --cwd x npm publish`).
  let underYarn = false;
  for (const [at, word] of words.entries()) {
    const tool = basename(word.text);
    const published = publishAt(tool, words, at, underYarn);
    if (published === 'script') break;
    if (published) found.set(at, published);
    underYarn ||= tool === 'yarn';
  }
  return found;
}

// The publish a word starts, when `tool` (its basename) is a publisher:
// `npm publish`, `pnpm -r publish`, `cargo +nightly publish`. `script` when
// the words after it are a package script's.
function publishAt(
  tool: string,
  words: Word[],
  at: number,
  underYarn: boolean,
): GhAction | 'script' | null {
  const name = tool.replace(/@[^/]*$/, '');
  const publisher = Object.hasOwn(PUBLISHERS, name) ? PUBLISHERS[name] : undefined;
  if (publisher === undefined) return null;
  let i = at + 1;
  while (i < words.length) {
    const t = words[i]?.text ?? '';
    if (name === 'cargo' && t.startsWith('+')) i++;
    else if (publisher.values.has(t)) i += 2;
    else if (t.startsWith('-') || publisher.passes?.has(t)) i++;
    else break;
  }
  const command = words[i];
  if (command === undefined) return null;
  const later = words.slice(i + 1).map((w) => w.text);
  if (command.dynamic) {
    if (!later.some((t) => publishes(publisher, t))) return null;
    return {
      kind: 'unread',
      why: `its \`${name}\` command is built at run time`,
      remedy: 'Write the command out.',
    };
  }
  if (RUNS_SCRIPTS.has(name) && /^(run|run-script)$/.test(command.text)) return 'script';
  if (!publishes(publisher, command.text)) return null;
  // `yarn npm publish` is Yarn's, whose dry run the gate does not know.
  const dryRuns = publisher.dryRuns && !(name === 'npm' && underYarn);
  const all = words.slice(at + 1).map((w) => w.text);
  return dryRuns && dryRun(name, all) ? null : { kind: 'release' };
}

